window.QUESTION_BANK = [{"id": "q1", "sourceId": "1", "prompt": "You execute this command:\n\n[[IMG:image1.png]]\n\nSufficient storage is available in filesystem /u01.\nWhich two statements are true about the BIG_TBS tablespace? (Choose two.)", "options": [{"id": "A", "text": "AUTOEXTEND is possible for the datafile"}, {"id": "B", "text": "It must be bigger than the largest SMALLFILE tablespace"}, {"id": "C", "text": "Additional data files may not be added"}, {"id": "D", "text": "It will be a dictionary-managed tablespace by default"}, {"id": "E", "text": "It will always have a 32K blocksize"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q2", "sourceId": "2", "prompt": "Which statement is true about the INTERSECT operator used in compound queries?", "options": [{"id": "A", "text": "Multiple INTERSECT operators are not possible in the same SQL statement"}, {"id": "B", "text": "It processes NULLs in the selected columns"}, {"id": "C", "text": "INTERSECT is of lower precedence than UNION or UNION ALL"}, {"id": "D", "text": "It ignores NULLs"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q3", "sourceId": "3", "prompt": "Which three statements are true about advanced connection options supported by Oracle Net for connection to Oracle Database instances? (Choose three.)", "options": [{"id": "A", "text": "Connect Time Failover requires the use of Transparent Application Failover (TAF)"}, {"id": "B", "text": "Source Routing requires the use of a name server"}, {"id": "C", "text": "Source Routing enables the use of Connection Manager (CMAN) which enables network traffic to be routed through a firewall"}, {"id": "D", "text": "Load Balancing can balance the number of connections to dispatchers when using a Shared Server configuration"}, {"id": "E", "text": "Load Balancing requires the use of a name server"}, {"id": "F", "text": "Connect Time Failover requires the connect string to have two or more listener addresses configured"}], "correct": ["C", "D", "F"], "choose": 3, "scorable": true}, {"id": "q4", "sourceId": "4", "prompt": "Which three statements are true about Resumable Space Allocation in Oracle databases? (Choose three.)", "options": [{"id": "A", "text": "A user's session may be suspended and resumed multiple times."}, {"id": "B", "text": "The AFTER SUSPEND event trigger can itself be suspended due to space conditions."}, {"id": "C", "text": "All sessions must have the same timeout value when waiting for resumable space allocations."}, {"id": "D", "text": "Resumable space allocation is only possible with locally managed tablespaces."}, {"id": "E", "text": "A user's session may be suspended even if the user has the UNLTMTTED TABLESPACE system privilege."}, {"id": "F", "text": "Resumable space allocation may be enabled for some sessions and not others."}], "correct": ["A", "E", "F"], "choose": 3, "scorable": true}, {"id": "q5", "sourceId": "5", "prompt": "A database is configured to use automatic undo management with temporary undo enabled.\nAn UPDATE is executed on a temporary table.\nWhere is the UNDO stored?", "options": [{"id": "A", "text": "in the undo tablespace"}, {"id": "B", "text": "in the SYSAUX tablespace"}, {"id": "C", "text": "in the SGA"}, {"id": "D", "text": "in the PGA"}, {"id": "E", "text": "in the temporary tablespacee"}], "correct": ["E"], "choose": 1, "scorable": true}, {"id": "q6", "sourceId": "50", "prompt": "View the Exhibits and examine the structure of the COSTS and PROMOTIONS tables.\nYou want to display PROD_IDS whose promotion cost is less than the highest cost PROD_ID in a promotion time interval.\nExamine this SQL statement:\n\n[[IMG:image2.png]]\n\nWhat will be the result?", "options": [{"id": "A", "text": "It gives an error because the ALL keyword is not valid"}, {"id": "B", "text": "It gives an error because the GROUP BY clause is not valid"}, {"id": "C", "text": "It executes successfully but does not give the required result"}, {"id": "D", "text": "It executes successfully and gives the required result\nExhibit 1.\n\n[[IMG:image3.png]]\n\nExhibit 2.\n\n[[IMG:image4.png]]"}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q7", "sourceId": "6", "prompt": "Table EMPLOYEES contains columns including EMPLOYEE_ID, JOB_ID and SALARY.\nOnly the EMPLOYEE_ID column is indexed.\nRows exist for employees 100 and 200.\nExamine this statement:\n\n[[IMG:image5.png]]\n\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "Employee 100 will have SALARY set to the same value as the SALARY of employee 200"}, {"id": "B", "text": "Employee 200 will have JOB_ID set to the same value as the JOB_ID of employee 100"}, {"id": "C", "text": "Employee 200 will have SALARY set to the same value as the SALARY of employee 100"}, {"id": "D", "text": "Employee 100 will have JOB_ID set to the same value as the JOB_ID of employee 200"}, {"id": "E", "text": "Employees 100 and 200 will have the same JOB_ID as before the update command"}, {"id": "F", "text": "Employees 100 and 200 will have the same SALARY as before the update command"}], "correct": [], "choose": 2, "scorable": false}, {"id": "q8", "sourceId": "7", "prompt": "In the spfile of a single instance database, LOCAL_LISTENER is set to LISTENER_1.\nThe TNSNAMES.ORA file in $ORACLE_HOME/network/admin in the database home contains:\n\n[[IMG:image6.png]]\n\nWhich statement is true?", "options": [{"id": "A", "text": "Dynamic service registration cannot be used for this database instance"}, {"id": "B", "text": "The LREG process registers services dynamically with the LISTENER_1 listener"}, {"id": "C", "text": "LISTENER_1 must also be defined in the LISTENER.ORA file to enable dynamic service registration"}, {"id": "D", "text": "There are two listeners named LISTENER and LISTENER_1 running simultaneously using port 1521 on the same host as the database instances"}, {"id": "E", "text": "The definition for LISTENER_1 requires a CONNECT_DATA section to enable dynamic service registration"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q9", "sourceId": "8", "prompt": "Which three statements are true concerning logical and physical database structures? (Choose three.)", "options": [{"id": "A", "text": "All tablespaces may have one or more data files"}, {"id": "B", "text": "The extents of a segment must always reside in the same datafile"}, {"id": "C", "text": "A smallfile tablespace might be bigger than a bigfile tablespace"}, {"id": "D", "text": "A segment can span multiple data files in some tablespaces"}, {"id": "E", "text": "A segment's blocks can be of different sizes"}, {"id": "F", "text": "A segment might have only one extent"}, {"id": "G", "text": "Segments can span multiple tablespaces"}], "correct": ["C", "D", "F"], "choose": 3, "scorable": true}, {"id": "q10", "sourceId": "8-1", "prompt": "Which two statements are true concerning logical and physical database structure:", "options": [{"id": "A", "text": "A segment can span multiple data files in some tablespaces."}, {"id": "B", "text": "All tablespaces may have one or more data files."}, {"id": "C", "text": "A segment might have only one extent."}, {"id": "D", "text": "A segment’s blocks can be of different sizes."}, {"id": "E", "text": "Segments can span multiple tablespaces."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q11", "sourceId": "9", "prompt": "Which two statements are true regarding a SAVEPOINT? (Choose two.)", "options": [{"id": "A", "text": "Rolling back to a SAVEPOINT can undo a CREATE INDEX statement"}, {"id": "B", "text": "Rolling back to a SAVEPOINT can undo a TRUNCATE statement"}, {"id": "C", "text": "Only one SAVEPOINT may be issued in a transaction"}, {"id": "D", "text": "A SAVEPOINT does not issue a COMMIT"}, {"id": "E", "text": "Rolling back to a SAVEPOINT can undo a DELETE statement"}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q12", "sourceId": "10", "prompt": "Which three functions are performed by dispatchers in a shared server configuration? (Choose three.)", "options": [{"id": "A", "text": "writing inbound request to the common request queue from all shared server connections"}, {"id": "B", "text": "checking for outbound shared server responses on the common outbound response queue"}, {"id": "C", "text": "receiving inbound requests from processes using shared server connections"}, {"id": "D", "text": "sending each connection input request to the appropriate shared server input queue"}, {"id": "E", "text": "broadcasting shared server session responses back to requesters on all connections"}, {"id": "F", "text": "sending shared server session responses back to requesters on the appropriate connection"}], "correct": ["A", "C", "F"], "choose": 3, "scorable": true}, {"id": "q13", "sourceId": "10-1", "prompt": "Examine the description of the PRODUCT_STATUS table:\n\n\n[[IMG:image7.png]]\n\n\nThe STATUS column contains the values 'IN STOCK' or 'OUT OF STOCK' for each row.\n\nWhich two queries will execute successfully? (Choose two.)", "options": [{"id": "A", "text": "[[IMG:image8.png]]"}, {"id": "B", "text": "[[IMG:image9.png]]"}, {"id": "C", "text": "[[IMG:image10.png]]"}, {"id": "D", "text": "[[IMG:image11.png]]"}, {"id": "E", "text": "[[IMG:image12.png]]"}, {"id": "F", "text": "[[IMG:image13.png]]"}], "correct": ["D", "F"], "choose": 2, "scorable": true}, {"id": "q14", "sourceId": "11", "prompt": "Which two statements are true about the SET VERIFY ON command? (Choose two.)", "options": [{"id": "A", "text": "It can be used only in SQL*Plus"}, {"id": "B", "text": "It displays values for variables used only in the WHERE clause of a query"}, {"id": "C", "text": "It can be used in SQL Developer and SQL*Plus"}, {"id": "D", "text": "It displays values for variables created by the DEFINE command"}, {"id": "E", "text": "It displays values for variables prefixed with &&"}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q15", "sourceId": "12", "prompt": "Which three statements are true about a self join? (Choose three.)", "options": [{"id": "A", "text": "The ON clause must be used"}, {"id": "B", "text": "The query must use two different aliases for the table"}, {"id": "C", "text": "It must be an equijoin"}, {"id": "D", "text": "It must be an inner join"}, {"id": "E", "text": "The ON clause can be used"}, {"id": "F", "text": "It can be an outer join"}], "correct": ["B", "E", "F"], "choose": 3, "scorable": true}, {"id": "q16", "sourceId": "14-1", "prompt": "You want to write a query that prompts for two column names and the WHERE condition each time it is executed in a session but only prompts for the table name the first time it is executed.\nThe variables used in your query are never undefined in your session.\nWhich query can be used?", "options": [{"id": "A", "text": "SELECT &&col1, &&col2 FROM &table WHERE &&condition = &&cond;"}, {"id": "B", "text": "SELECT &col1, &col2 FROM &&table WHERE &condition;"}, {"id": "C", "text": "SELECT &col1, &col2 FROM &table WHERE &condition;"}, {"id": "D", "text": "SELECT '&&col1', '&&col2' FROM &table WHERE '&&condition' = '&cond';"}, {"id": "E", "text": "SELECT &&col1, &&col2 FROM &table WHERE &&condition;"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q17", "sourceId": "14", "prompt": "Examine the description of the CUSTOMERS table:\n\n[[IMG:image14.png]]\n\nYou want to display details of all customers who reside in cities starting with the letter D followed by at least two characters.\nWhich query can be used?", "options": [{"id": "A", "text": "SELECT * FROM customers WHERE city LIKE 'D_%';"}, {"id": "B", "text": "SELECT * FROM customers WHERE city = '%D_';"}, {"id": "C", "text": "SELECT * FROM customers WHERE city LIKE 'D_';"}, {"id": "D", "text": "SELECT * FROM customers WHERE city = 'D_%';"}], "correct": ["A"], "choose": 1, "scorable": true}, {"id": "q18", "sourceId": "15", "prompt": "Examine this command:\n\n[[IMG:image15.png]]\n\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "DML may be performed on tables with one or more extents in this data file during the execution of this command."}, {"id": "B", "text": "The tablespace containing SALES1.DBF must be altered READ ONLY before executing the command."}, {"id": "C", "text": "The tablespace containing SALES1.DBF must be altered OFFLINE before executing the command."}, {"id": "D", "text": "If Oracle Managed Files (OMF) is used, then the file is renamed but moved to DB_CREATE_FILE_DEST."}, {"id": "E", "text": "The file is renamed and stored in the same location"}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q19", "sourceId": "16", "prompt": "Which three statements are true about dropping and unused columns in an Oracle database? (Choose three.)", "options": [{"id": "A", "text": "A primary key column referenced by another column as a foreign key can be dropped if using the CASCADE option."}, {"id": "B", "text": "An UNUSED column's space is reclaimed automatically when the block containing that column is next queried."}, {"id": "C", "text": "An UNUSED column's space is reclaimed automatically when the row containing that column is next queried."}, {"id": "D", "text": "Partition key columns cannot be dropped."}, {"id": "E", "text": "A DROP COLUMN command can be rolled back"}, {"id": "F", "text": "A column that is set to UNUSED still counts towards the limit of 1000 columns per table"}], "correct": ["A", "D", "F"], "choose": 3, "scorable": true}, {"id": "q20", "sourceId": "68", "prompt": "Which two statements are true about views used for viewing tablespace and datafile information? (Choose two.)", "options": [{"id": "A", "text": "Tablespace free space can be viewed in V$TABLESPACE"}, {"id": "B", "text": "V$TABLESPACE displays information that is contained in the controlfile about tablespaces"}, {"id": "C", "text": "V$TABLESPACE displays information about tablespaces contained in the data dictionary"}, {"id": "D", "text": "Tablespace free space can be viewed in DBA_TABLESPACES"}, {"id": "E", "text": "A datafile can be renamed when the database is in MOUNT state and the new file name is displayed when querying DBA_DATA_FILES after the database is opened"}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q21", "sourceId": "17", "prompt": "View the Exhibit and examine the description of the tables.\n\n[[IMG:image16.png]]\n\nYou execute this SQL statement:\n\n[[IMG:image17.png]]\n\nWhich three statements are true?", "options": [{"id": "A", "text": "The statement will fail if a row already exists in the SALES table for product 23."}, {"id": "B", "text": "The SALES table has five foreign keys."}, {"id": "C", "text": "The statement will execute successfully and a new row will be inserted into the SALES table."}, {"id": "D", "text": "A product can have a different unit price at different times."}, {"id": "E", "text": "The statement will fail because a subquery may not be contained in a VALUES clause."}, {"id": "F", "text": "A customer can exist in many countries."}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q22", "sourceId": "17-1", "prompt": "Which two Oracle database space management features require the use of locally managed tablespaces?", "options": [{"id": "A", "text": "Online segment shrink"}, {"id": "B", "text": "Automatic data file extension (AUTOEXTEND)"}, {"id": "C", "text": "Oracle Managed Files (OMF)"}, {"id": "D", "text": "Free space management with bitmaps."}, {"id": "E", "text": "Server-generated tablespace space alerts."}], "correct": ["A", "D"], "choose": 2, "scorable": true}, {"id": "q23", "sourceId": "17-2", "prompt": "Which three Oracle database space management features will work with both Dictionary and Locally managed tablespaces? (Choose three.)", "options": [{"id": "A", "text": "Oracle Managed Files (OMF)"}, {"id": "B", "text": "Online table segment shrink"}, {"id": "C", "text": "Online index segment shrink"}, {"id": "D", "text": "Automatic data file extension (AUTOEXTEND)"}, {"id": "E", "text": "Capacity planning growth reports based on historical data in the Automatic Workload Repository (AWR)"}], "correct": ["A", "D", "E"], "choose": 3, "scorable": true}, {"id": "q24", "sourceId": "17", "prompt": "Which two statements are true regarding Oracle database space management within blocks managed by Automatic Segment Space Management (ASSM)?\n(Choose two.)", "options": [{"id": "A", "text": "PCTFREE defaults to 10% for all blocks in all segments for all compression methods"}, {"id": "B", "text": "ASSM assigns blocks to one of four fullness categories based on what percentage of the block is allocated for rows"}, {"id": "C", "text": "Update operations always attempt to find blocks with free space appropriate to the length of the row being updated"}, {"id": "D", "text": "Insert operations always attempt to find blocks with free space appropriate to the length of the row being inserted"}, {"id": "E", "text": "A block will always be eligible for inserts if the row is short enough to fit into the block"}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q25", "sourceId": "18", "prompt": "Evaluate these commands which execute successfully:\n\n[[IMG:image18.png]]\n\nWhich two statements are true about the ORD_ITEMS table and the ORD_SEQ sequence? (Choose two.)", "options": [{"id": "A", "text": "If sequence ORD_SEQ is dropped then the default value for column ORD_NO will be NULL for rows inserted into ORD_ITEMS"}, {"id": "B", "text": "Any user inserting rows into table ORD_ITEMS must have been granted access to sequence ORD_SEQ"}, {"id": "C", "text": "Column ORD_NO gets the next number from sequence ORD_SEQ whenever a row is inserted into ORD_ITEMS and no explicit value is given for ORD_NO"}, {"id": "D", "text": "Sequence ORD_SEQ cycles back to 1 after every 5000 numbers and can cycle 20 times"}, {"id": "E", "text": "Sequence ORD_SEQ is guaranteed not to generate duplicate numbers"}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q26", "sourceId": "19", "prompt": "Which three instance situations are possible with the Oracle Database server without multi-tenant? (Choose three.)", "options": [{"id": "A", "text": "two or more instances on separate servers all associated with one database"}, {"id": "B", "text": "one instance on one server associated with one database"}, {"id": "C", "text": "one instance on one server associated with two or more databases on the same server"}, {"id": "D", "text": "one instance on one server not associated with any database"}, {"id": "E", "text": "one instance on one server associated with two or more databases on separate servers"}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q27", "sourceId": "20", "prompt": "Which two statements are true about the ORDER BY clause when used with a SQL statement containing a SET operator such as UNION? (Choose two.)", "options": [{"id": "A", "text": "Column positions must be used in the ORDER BY clause"}, {"id": "B", "text": "Only column names from the first SELECT statement in the compound query are recognized"}, {"id": "C", "text": "The first column in the first SELECT of the compound query with the UNION operator is used by default to sort output in the absence of an ORDER BY clause"}, {"id": "D", "text": "Each SELECT statement in the compound query must have its own ORDER BY clause"}, {"id": "E", "text": "Each SELECT statement in the compound query can have its own ORDER BY clause"}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q28", "sourceId": "20-1", "prompt": "Which four account management capabilities can be configured using Oracle profiles? (Choose four.)", "options": [{"id": "A", "text": "the number of hours for which an account is locked after the configured number of login attempts has been reached"}, {"id": "B", "text": "the number of days for which an account may be inactive before it is locked"}, {"id": "C", "text": "the maximum amount of CPU time allowed for a user's sessions before their account is locked"}, {"id": "D", "text": "the ability to prevent a password from ever being reused"}, {"id": "E", "text": "the number of password changes required within a period of time before a password can be reused"}, {"id": "F", "text": "the number of days for which an account is locked after the configured number of login attempts has been reached"}, {"id": "G", "text": "the maximum number of sessions permitted for a user before the account is locked"}], "correct": ["A", "B", "D", "E", "F"], "choose": 4, "scorable": false}, {"id": "q29", "sourceId": "21", "prompt": "Which three statements are true about single-row functions? (Choose three.)", "options": [{"id": "A", "text": "They can be used only in the WHERE clause of a SELECT statement"}, {"id": "B", "text": "The argument can be a column name, variable, literal or an expression"}, {"id": "C", "text": "The data type returned can be different from the data type of the argument"}, {"id": "D", "text": "They can be nested to any level"}, {"id": "E", "text": "They can accept only one argument"}, {"id": "F", "text": "They return a single result row per table"}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q30", "sourceId": "23", "prompt": "You want to use table compression suitable for OLTP that will:\n1. Compress rows for all DML statements on that table\n2. Minimize the overheads associated with compression\nWhich compression option is best suited for this?", "options": [{"id": "A", "text": "COLUMN STORE COMPRESS FOR QUERY LOW"}, {"id": "B", "text": "ROW STORE COMPRESS BASIC"}, {"id": "C", "text": "COLUMN STORE COMPRESS FOR ARCHIVE LOW"}, {"id": "D", "text": "COLUMN STORE COMPRESS FOR ARCHIVE HIGH"}, {"id": "E", "text": "ROW STORE COMPRESS ADVANCED"}], "correct": ["E"], "choose": 1, "scorable": true}, {"id": "q31", "sourceId": "23-1", "prompt": "Which compression method is recommended for Direct-Path Insert operations", "options": [{"id": "A", "text": "ROW STORE COMPRESS ADVANCED"}, {"id": "B", "text": "COLUMN STORE COMPRESS ADVANCED"}, {"id": "C", "text": "ROW STORE COMPRESS BASIC"}, {"id": "D", "text": "COLUMN STORE COMPRESS BASIC"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q32", "sourceId": "26", "prompt": "In which three situations does a new transaction always start? (Choose three.)", "options": [{"id": "A", "text": "when issuing a SELECT FOR UPDATE statement after a CREATE TABLE AS SELECT statement was issued in the same session"}, {"id": "B", "text": "when issuing a TRUNCATE statement after a SELECT statement was issued in the same session"}, {"id": "C", "text": "when issuing a CREATE TABLE statement after a SELECT statement was issued in the same session"}, {"id": "D", "text": "when issuing the first Data Manipulation Language (DML) statement after a COMMIT OR ROLLBACK statement was issued in the same session"}, {"id": "E", "text": "when issuing a CREATE INDEX statement after a CREATE TABLE statement completed successfully in the same session"}, {"id": "F", "text": "when issuing a DML statement after a DML statement failed in the same session"}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q33", "sourceId": "27", "prompt": "Examine the description of the SALES1 table:\n\n[[IMG:image19.png]]\n\nSALES2 is a table with the same description as SALES1.\nSome sales data is duplicated in both tables.\nYou want to display the rows from the SALES1 table which are not present in the SALES2 table.\nWhich set operator generates the required output?", "options": [{"id": "A", "text": "INTERSECT"}, {"id": "B", "text": "UNION ALL"}, {"id": "C", "text": "UNION"}, {"id": "D", "text": "SUBTRACT"}, {"id": "E", "text": "MINUS"}], "correct": ["E"], "choose": 1, "scorable": true}, {"id": "q34", "sourceId": "28", "prompt": "Your database instance is started with a PFILE.\nExamine these parameters:\n\n[[IMG:image20.png]]\n You want to increase the size of the buffer cache.\nFree memory is available to increase the size of the buffer cache.\nYou execute the command:\nSQL> ALTER SYSTEM SET DB_CACHE_SIZE=1024M;\nWhat is the outcome?", "options": [{"id": "A", "text": "The value is changed only in the PFILE and takes effect at the next instance startup"}, {"id": "B", "text": "The value is changed for the current instance and in the PFILE"}, {"id": "C", "text": "It fails because the SCOPE clause is missing"}, {"id": "D", "text": "Change is applied to the current instance, but does not persist after instance restart"}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q35", "sourceId": "30", "prompt": "You execute this command:\n\n[[IMG:image21.png]]\n\nDuring the export operation, you detach from the job by using CTRL+C and then execute this command:\n\nExport> STOP_JOB=immediate -\nAre you sure you wish to stop the job ([yes]/no): yes\nWhich two statements are true about the job? (Choose two.)", "options": [{"id": "A", "text": "You can no longer monitor it"}, {"id": "B", "text": "You can reattach to it and monitor it"}, {"id": "C", "text": "It is paused and can be resumed"}, {"id": "D", "text": "It continues to run in the background"}, {"id": "E", "text": "It terminates"}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q36", "sourceId": "31", "prompt": "In one of your databases, you create a user, HR, and then execute this command:\nGRANT CREATE SESSION TO hr WITH ADMIN OPTION;\nWhich four actions can HR perform? (Choose four.)", "options": [{"id": "A", "text": "Revoke the CREATE SESSION privilege from other users"}, {"id": "B", "text": "Revoke the CREATE SESSION privilege from user HR"}, {"id": "C", "text": "Log in to the database instance"}, {"id": "D", "text": "Grant the CREATE SESSION privilege with ADMIN OPTION to other users"}, {"id": "E", "text": "Execute DDL statements in the HR schema"}, {"id": "F", "text": "Execute DML statements in the HR schema"}], "correct": ["A", "B", "D"], "choose": 4, "scorable": false}, {"id": "q37", "sourceId": "32", "prompt": "Which two statements are true about the WHERE and HAVING clauses in a SELECT statement? (Choose two.)", "options": [{"id": "A", "text": "Aggregating functions and columns used in HAVING clauses must be specified in the SELECT list of a query"}, {"id": "B", "text": "WHERE and HAVING clauses can be used in the same statement only if applied to different table columns"}, {"id": "C", "text": "The HAVING clause can be used with aggregating functions in subqueries"}, {"id": "D", "text": "The WHERE clause can be used to exclude rows before dividing them into groups"}, {"id": "E", "text": "The WHERE clause can be used to exclude rows after dividing them into groups"}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q38", "sourceId": "33", "prompt": "Which two statements are true about UNDO and REDO? (Choose two.)", "options": [{"id": "A", "text": "The generation of UNDO generates REDO"}, {"id": "B", "text": "DML modifies Oracle database objects and only generates UNDO"}, {"id": "C", "text": "The generation of REDO generates UNDO"}, {"id": "D", "text": "DML modifies Oracle database objects and only generates REDO"}, {"id": "E", "text": "DML modifies Oracle database objects and generates UNDO and REDO"}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q39", "sourceId": "34", "prompt": "The SCOTT/TIGER user exists in two databases, BOSTON_DB and DALLAS_DB, in two different locations.\nEach database has a tnsnames.ora file defining DALLAS_DB as a service name.\nExamine this command:\nCREATE DATABASE LINK dblink1 CONNECT TO scott IDENTIFIED BY tiger USING 'dallas_db';\nHow do you execute the command so that only SCOTT in BOSTON_DB can access the SCOTT schema in DALLAS_DB?", "options": [{"id": "A", "text": "as SCOTT in DALLAS_DB"}, {"id": "B", "text": "as SCOTT in BOSTON_DB"}, {"id": "C", "text": "as SCOTT in BOSTON_DB and SYS in DALLAS_DB"}, {"id": "D", "text": "as SYS in both the databases"}, {"id": "E", "text": "as SCOTT in both the databases"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q40", "sourceId": "35", "prompt": "Which three statements are true about the DESCRIBE command? (Choose three.)", "options": [{"id": "A", "text": "It displays the PRIMARY KEY constraint for any column or columns that have that constraint"}, {"id": "B", "text": "It can be used from SQL Developer"}, {"id": "C", "text": "It displays the NOT NULL constraint for any columns that have that constraint"}, {"id": "D", "text": "It can be used to display the structure of an existing view"}, {"id": "E", "text": "It displays all constraints that are defined for each column"}, {"id": "F", "text": "It can be used only from SQL*Plus"}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q41", "sourceId": "36", "prompt": "Examine the description of the CUSTOMERS table:\n\nFor customers whose income level has a value, you want to display the first name and due amount as 5% of their credit limit. Customers whose due amount is null should not be displayed.\nWhich query should be used?", "options": [{"id": "A", "text": "SELECT cust_first_name, cust_credit_limit * .05 AS DUE_AMOUNT FROM customers WHERE cust_income_level IS NOT NULL AND due_amount IS NOT NULL;"}, {"id": "B", "text": "SELECT cust_first_name, cust_credit_limit * .05 AS DUE_AMOUNT FROM customers WHERE cust_income_level != NULL AND cust_credit_level !=NULL;"}, {"id": "C", "text": "SELECT cust_first_name, cust_credit_limit * .05 AS DUE_AMOUNT FROM customers WHERE cust_income_level <> NULL AND due_amount <> NULL;"}, {"id": "D", "text": "SELECT cust_first_name, cust_credit_limit * .05 AS DUE_AMOUNT FROM customers WHERE cust_income_level != NULL AND due_amount != NULL;"}, {"id": "E", "text": "SELECT cust_first_name, cust_credit_limit * .05 AS DUE_AMOUNT FROM customers WHERE cust_income_level IS NOT NULL AND cust_credit_limit IS NOT NULL;"}], "correct": ["E"], "choose": 1, "scorable": true}, {"id": "q42", "sourceId": "37", "prompt": "The INVOICE table has a QTY_SOLD column of data type NUMBER and an INVOICE_DATE column of data type DATE.\nNLS_DATE_FORMAT is set to DD-MON-RR.\nWhich two are true about data type conversions involving these columns in query expressions? (Choose two.)", "options": [{"id": "A", "text": "CONCAT (qty_sold, invoice_date) : requires explicit conversion"}, {"id": "B", "text": "invoice_date = '15-march-2019' : uses implicit conversion"}, {"id": "C", "text": "invoie_date > '01-02-2019' : uses implicit conversion"}, {"id": "D", "text": "qty_sold BETWEEN '101' AND '110' : uses implicit conversion"}, {"id": "E", "text": "qty_sold = '0554982' uses implicit conversion"}], "correct": ["B", "D", "E"], "choose": 2, "scorable": false}, {"id": "q43", "sourceId": "38", "prompt": "Which three are types of segments in an Oracle Database? (Choose three.)", "options": [{"id": "A", "text": "undo"}, {"id": "B", "text": "index"}, {"id": "C", "text": "stored procedures"}, {"id": "D", "text": "sequences"}, {"id": "E", "text": "tables"}, {"id": "F", "text": "clusters"}], "correct": ["B", "E", "F"], "choose": 3, "scorable": true}, {"id": "q44", "sourceId": "39", "prompt": "Which two statements are true about the results of using the INTERSECT operator in compound queries? (Choose two.)", "options": [{"id": "A", "text": "Column names in each SELECT in the compound query can be different"}, {"id": "B", "text": "The number of columns in each SELECT in the compound query can be different"}, {"id": "C", "text": "Reversing the order of the intersected tables can sometimes affect the output"}, {"id": "D", "text": "INTERSECT returns rows common to both sides of the compound query"}, {"id": "E", "text": "INTERSECT ignores NULLs"}], "correct": ["A", "D"], "choose": 2, "scorable": true}, {"id": "q45", "sourceId": "40", "prompt": "Which two statements are true about single row functions? (Choose two.)", "options": [{"id": "A", "text": "MOD : returns the quotient of a division operation"}, {"id": "B", "text": "FLOOR : returns the smallest integer greater than or equal to a specified number"}, {"id": "C", "text": "TRUNC : can be used with NUMBER and DATE values"}, {"id": "D", "text": "CONCAT : can be used to combine any number of values"}, {"id": "E", "text": "CEIL : can be used for positive and negative numbers"}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q46", "sourceId": "40-1", "prompt": "Which three statements are true about Deferred Segment Creation in Oracle databases?", "options": [{"id": "A", "text": "Indexes inherit the DEFERRED or IMMEDIATE segment creation attribute from their parent table"}, {"id": "B", "text": "Sessions may dynamically switch back and forth from DEFERRED to IMMEDIATE segment creation"}, {"id": "C", "text": "It is the default behavior for tables and indexes"}, {"id": "D", "text": "It is supported for Index Organized Tables (IOTs) contained in locally managed tablespaces"}, {"id": "E", "text": "It is supported for SYS-owned tables contained in locally managed tablespaces"}], "correct": ["A", "B", "C"], "choose": 3, "scorable": true}, {"id": "q47", "sourceId": "41", "prompt": "The EMPLOYEES table contains columns EMP_ID of data type NUMBER and HIRE_DATE of data type DATE.\nYou want to display the date of the first Monday after the completion of six months since hiring.\nThe NLS_TERRITORY parameter is set to AMERICA in the session and, therefore, Sunday is the first day on the week.\nWhich query can be used?", "options": [{"id": "A", "text": "SELECT emp_id, ADD_MONTHS(hire_date, 6), NEXT_DAY('MONDAY') FROM employees;"}, {"id": "B", "text": "SELECT emp_id, NEXT_DAY(ADD_MONTHS(hire_date, 6), 'MONDAY') FROM employees;"}, {"id": "C", "text": "SELECT emp_id, NEXT_DAY(MONTHS_BETWEEN(hire_date, SYSDATE), 6) FROM employees;"}, {"id": "D", "text": "SELECT emp_id, NEXT_DAY(ADD_MONTHS(hire_date, 6), 1) FROM employees;"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q48", "sourceId": "41", "prompt": "Which three statements are true about the Oracle Data Dictionary? (Choose three.)", "options": [{"id": "A", "text": "Data dictionary views are created by joins of dictionary base tables and DBA-defined tables"}, {"id": "B", "text": "The data dictionary is created and maintained by the database administrator"}, {"id": "C", "text": "Views with the same name but different prefixes, such as CDB, DBA, ALL and USER, reference the same base tables from the data dictionary"}, {"id": "D", "text": "Base tables can be queried directly"}, {"id": "E", "text": "It is owned by the SYSTEM user"}, {"id": "F", "text": "Usernames of all users including database administrators are stored in the data dictionary"}], "correct": ["C", "D", "F"], "choose": 3, "scorable": true}, {"id": "q49", "sourceId": "44", "prompt": "In one of your databases, the user HR has the password HRMGR.\nYou want to connect to a database instance whose listener listens on port 1531 by using this statement:\n\nCONNECT HR/HRMGR@orcl -\nNo name server is used.\nWhich statement is true about ORCL?", "options": [{"id": "A", "text": "It must be the value of the SERVICE_NAMES parameter on the client side"}, {"id": "B", "text": "It must resolve to a valid connect descriptor in the server's tnsnames.ora file"}, {"id": "C", "text": "It must resolve to a valid connect descriptor in the client's tnsnames.ora file"}, {"id": "D", "text": "It must be the name of the database to whose instance HR wishes to connect"}, {"id": "E", "text": "It must be the name of the server running the database to whose instance HR wishes to connect"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q50", "sourceId": "46", "prompt": "Examine the description of the PROMOTIONS table:\n\n[[IMG:image22.png]]\n\nYou want to display the unique promotion costs in each promotion category.\nWhich two queries can be used? (Choose two.)", "options": [{"id": "A", "text": "SELECT promo_cost, promo_category FROM promotions ORDER BY by 1;"}, {"id": "B", "text": "SELECT DISTINCT promo_cost || ' in ' || DISTINCT promo_category FROM promotions ORDER BY 1;"}, {"id": "C", "text": "SELECT DISTINCT promo_category || ' has ' || promo_cost AS COSTS FROM promotions ORDER BY 1;"}, {"id": "D", "text": "SELECT promo_category, DISTINCT promo_cost FROM promotions ORDER BY 2;"}, {"id": "E", "text": "SELECT DISTINCT promo_category, promo_cost FROM promotions ORDER BY 1;"}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q51", "sourceId": "47", "prompt": "In the ORCL database, UNDOTBS1 is the active undo tablespace with these properties:\n1. A size of 100 MB\n2. AUTOEXTEND is off\n3. UNDO_RETENTION is set to 15 minutes\n4. It has RETENTION GUARANTEE\nUNDOTBS1 fills with uncommitted undo 10 minutes after the database opens.\nWhat will happen when the next update is attempted by any transaction?", "options": [{"id": "A", "text": "It succeeds and the generated undo is stored in SYSTEM."}, {"id": "B", "text": "It fails and returns the error message ג€ORA-30036: unable to extend segment by 8 in undo tablespace 'UNDOTBS1'ג€."}, {"id": "C", "text": "It succeeds and the least recently written undo block of UNDOTBS1 is overwritten by the generated undo."}, {"id": "D", "text": "It succeeds and the generated undo is stored in SYSAUX."}, {"id": "E", "text": "It succeeds and the least recently read undo block of UNDOTBS1 is overwritten by the generated undo."}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q52", "sourceId": "48", "prompt": "Which two statements are true about the rules of precedence for operators? (Choose two.)", "options": [{"id": "A", "text": "The concatenation operator | | is always evaluated before addition and subtraction in an expression"}, {"id": "B", "text": "NULLS influence the precedence of operators in an expression"}, {"id": "C", "text": "The + binary operator has the highest precedence in an expression in a SQL statement"}, {"id": "D", "text": "Arithmetic operators with equal precedence are evaluated from left to right within an expression"}, {"id": "E", "text": "Multiple parentheses can be used to override the default precedence of operators in an expression"}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q53", "sourceId": "49", "prompt": "In one of your databases, user KING is:\n1. Not a DBA user\n2. An operating system (OS) user\nExamine this command and its output:\n\n[[IMG:image23.png]]\n What must you do so that KING is authenticated by the OS when connecting to the database instance?", "options": [{"id": "A", "text": "Set OS_AUTHENT_PREFIX to OPS$"}, {"id": "B", "text": "Have the OS administrator add KING to the OSDBA group"}, {"id": "C", "text": "Grant DBA to KING"}, {"id": "D", "text": "Unset REMOTE_LOGIN_PASSWORDFILE"}, {"id": "E", "text": "Alter user KING to be IDENTIFIED EXTERNALLY"}], "correct": ["E"], "choose": 1, "scorable": true}, {"id": "q54", "sourceId": "51", "prompt": "Which three statements are true about GLOBAL TEMPORARY TABLES? (Choose three.)", "options": [{"id": "A", "text": "A TRUNCATE command issued in a session causes all rows in a GLOBAL TEMPORARY TABLE for the issuing session to be deleted."}, {"id": "B", "text": "GLOBAL TEMPORARY TABLE rows inserted by a session are available to any other session whose user has been granted select on the table."}, {"id": "C", "text": "GLOBAL TEMPORARY TABLE space allocation occurs at session start."}, {"id": "D", "text": "Any GLOBAL TEMPORARY TABLE rows existing at session termination will be deleted."}, {"id": "E", "text": "A GLOBAL TEMPORARY TABLE'S definition is available to multiple sessions."}, {"id": "F", "text": "A DELETE command on a GLOBAL TEMPORARY TABLE cannot be rolled back."}], "correct": ["A", "D", "E"], "choose": 3, "scorable": true}, {"id": "q55", "sourceId": "52", "prompt": "Which two statements are true about trace files produced by the Oracle Database server? (Choose two.)", "options": [{"id": "A", "text": "They can be written by server processes"}, {"id": "B", "text": "Trace files are written to the Fast Recovery Area (FRA)"}, {"id": "C", "text": "They can be written by background processes"}, {"id": "D", "text": "All trace files contain error information that require contacting Oracle Support"}, {"id": "E", "text": "Trace file names are based on the database name concatenated with a sequential number"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q56", "sourceId": "53", "prompt": "", "options": [], "correct": [], "choose": 0, "scorable": false}, {"id": "q57", "sourceId": "54", "prompt": "Which two statements are true about the DUAL table? (Choose two.)", "options": [{"id": "A", "text": "It can be accessed only by the SYS user"}, {"id": "B", "text": "It consists of a single row and single column of VARCHAR2 data type"}, {"id": "C", "text": "It can display multiple rows but only a single column"}, {"id": "D", "text": "It can be used to display only constants or pseudo columns"}, {"id": "E", "text": "It can be accessed by any user who has the SELECT privilege in any schema"}, {"id": "F", "text": "It can display multiple rows and columns"}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q58", "sourceId": "55", "prompt": "Which four statements are true regarding primary and foreign key constraints and the effect they can have on table data? (Choose four.)", "options": [{"id": "A", "text": "A table can have only one primary key but multiple foreign keys"}, {"id": "B", "text": "A table can have only one primary key and one foreign key"}, {"id": "C", "text": "The foreign key columns and parent table primary key columns must have the same names"}, {"id": "D", "text": "It is possible for child rows that have a foreign key to remain in the child table at the time the parent row is deleted"}, {"id": "E", "text": "It is possible for child rows that have a foreign key to be deleted automatically from the child table at the time the parent row is deleted"}, {"id": "F", "text": "Only the primary key can be defined at the column and table level"}, {"id": "G", "text": "Primary key and foreign key constraints can be defined at both the column and table level"}], "correct": ["A", "D", "E", "G"], "choose": 4, "scorable": true}, {"id": "q59", "sourceId": "57", "prompt": "What is true about non-equijoin statement performance? (Choose two.)", "options": [{"id": "A", "text": "Table aliases can improve performance"}, {"id": "B", "text": "The BETWEEN condition always performs better than using the >= and <= conditions"}, {"id": "C", "text": "The join syntax used makes no difference to performance"}, {"id": "D", "text": "The BETWEEN condition always performs less well than using the >= and <= conditions"}, {"id": "E", "text": "The Oracle join syntax performs better than the SQL:1999 compliant ANSI join syntax"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q60", "sourceId": "58", "prompt": "In your data center, Oracle Managed Files (OMF) is used for all databases.\nAll tablespaces are smallfile tablespaces.\nSALES_Q1 is a permanent user-defined tablespace in the SALES database.\nExamine this command which is about to be issued by a DBA logged in to the SALES database:\nALTER TABLESPACE sales_q1 ADD DATAFILE;\nWhich are two actions, either one of which you could take to ensure that the command executes successfully? (Choose two.)", "options": [{"id": "A", "text": "Ensure that DB_RECOVERY_FILE_DEST and DB_CREATE_FILE_DEST each specify with at least 50 Mb of available space."}, {"id": "B", "text": "Specify a path in the DATAFILE clause of the command specifying a location with at least 100M of available space."}, {"id": "C", "text": "Ensure that DB_CREATE_FILE_DEST specifies a location with at least 100 Mb of available space."}, {"id": "D", "text": "Add the AUTOEXTEND ON clause with NEXT set to 100M."}, {"id": "E", "text": "Ensure that DB_RECOVERY_FILE_DEST and DB_CREATE_FILE_DEST each specify locations with at least 50 Mb of available space."}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q61", "sourceId": "59", "prompt": "Examine this command and some partial output:\n\n[[IMG:image24.png]]\n\nWhy does the DB01.abc.com service show unknown status?", "options": [{"id": "A", "text": "The service DB01.abc.com is dynamically registered"}, {"id": "B", "text": "The LOCAL_LISTENER database parameter is not set to a service name that refers to LISTENER_1"}, {"id": "C", "text": "The service DB01.abc.com is statically registered"}, {"id": "D", "text": "The listener is not listening on the default port 1521"}, {"id": "E", "text": "The SID_LIST_LISTENER section is not contained in the LISTENER.ORA file"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q62", "sourceId": "59-1", "prompt": "Which three are types of segments in a Oracle database?", "options": [{"id": "A", "text": "Sequences"}, {"id": "B", "text": "views"}, {"id": "C", "text": "tables"}, {"id": "D", "text": "clusters"}, {"id": "E", "text": "Undo"}, {"id": "F", "text": "stored procedures."}], "correct": ["C", "D", "E"], "choose": 3, "scorable": true}, {"id": "q63", "sourceId": "60", "prompt": "Which three statements are true about the tools used to configure Oracle Net Services? (Choose three.)", "options": [{"id": "A", "text": "The Oracle Net Configuration Assistant is only used when running the Oracle installer"}, {"id": "B", "text": "Oracle Net Manager can be used to centrally configure listeners on any database server target"}, {"id": "C", "text": "The lsnrctl utility requires a listener.ora file to exist before it is started"}, {"id": "D", "text": "Oracle Net Manager can be used to locally configure naming methods on a database server"}, {"id": "E", "text": "Enterprise Manager Cloud Control can be used to centrally configure listeners on any managed database server"}, {"id": "F", "text": "Enterprise Manager Cloud Control can be used to centrally configure net service names for any database server target"}], "correct": ["D", "E", "F"], "choose": 3, "scorable": true}, {"id": "q64", "sourceId": "237", "prompt": "Choose three. Which three statements are true about Enterprise Manager Cloud Control?", "options": [{"id": "A", "text": "It is available to manage a database only when that database is open."}, {"id": "B", "text": "It is integrated with My Oracle Support."}, {"id": "C", "text": "It provides management for Oracle middleware."}, {"id": "D", "text": "It provides management for Oracle-engineered systems."}, {"id": "E", "text": "It uses a web-based console built into the Oracle database using XML DB."}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q65", "sourceId": "61", "prompt": "Which two statements are true regarding the UNION and UNION ALL operators? (Choose two.)", "options": [{"id": "A", "text": "Duplicates are eliminated automatically by the UNION ALL operator"}, {"id": "B", "text": "The number of columns selected in each SELECT statement must be identical"}, {"id": "C", "text": "The names of columns selected in each SELECT statement must be identical"}, {"id": "D", "text": "The output is sorted by the UNION ALL operator"}, {"id": "E", "text": "NULLS are not ignored during duplicate checking"}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q66", "sourceId": "62", "prompt": "Which two statements are true about the Automatic Diagnostic Repository (ADR)? (Choose two.)", "options": [{"id": "A", "text": "The ADR base defaults to $ORACLE_HOME/rdbms/admin if neither DIAGNOSTIC_DEST nor ORACLE_BASE is set"}, {"id": "B", "text": "The ADR base defaults to $ORACLE_HOME/dbs if the DIAGNOSTIC_DEST parameter and the ORACLE_BASE environment variable are not set"}, {"id": "C", "text": "It supports diagnostics for Automatic Storage Management (ASM)"}, {"id": "D", "text": "It supports diagnostics for Oracle Clusterware"}, {"id": "E", "text": "It is held inside an Oracle database schema"}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q67", "sourceId": "62-1", "prompt": "Which two types of files are opened by a database instance in the NOMOUNT state?", "options": [{"id": "A", "text": "data files"}, {"id": "B", "text": "the initialization parameter file"}, {"id": "C", "text": "the alert log"}, {"id": "D", "text": "control files"}, {"id": "E", "text": "online redo logs"}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q68", "sourceId": "63-1", "prompt": "Which three statements are true about the Automatic Diagnostic Repository (ADR)?", "options": [{"id": "A", "text": "It is only used for Oracle Database diagnostic Information."}, {"id": "B", "text": "It is held inside an Oracle database schema."}, {"id": "C", "text": "It is a file-based repository held outside any database."}, {"id": "D", "text": "It can be used for problem diagnosis of a database when that database’s instance is down."}, {"id": "E", "text": "The ADR base is specified in the DIAGNOSTIC_DEST database parameter."}], "correct": ["C", "D", "E"], "choose": 3, "scorable": true}, {"id": "q69", "sourceId": "63", "prompt": "You want to apply the principle of Least Privilege in all your live databases.\nOne of your requirements is to revoke unnecessary privileges from all users who have them using Privilege Analysis.\nWhich three types of analyses can be done using the DBMS_PRIVILEGE_CAPTURE package? (Choose three.)", "options": [{"id": "A", "text": "analysis of all privileges used by all users including administrative users in the database"}, {"id": "B", "text": "analysis of all privileges used by all users but excluding administrative users in the database"}, {"id": "C", "text": "analysis of privileges that a user has on their own schema objects that they did not use"}, {"id": "D", "text": "analysis of privileges that a user has on their own schema objects that they did use"}, {"id": "E", "text": "analysis of privileges granted directly to a role that are then used by a user who has been granted that role"}, {"id": "F", "text": "analysis of privileges granted indirectly to a role that are then used by a user who has been granted that role"}], "correct": ["C", "E", "F"], "choose": 3, "scorable": true}, {"id": "q70", "sourceId": "63-1", "prompt": "You want to apply the principle of Least Privilege in all your live databases.\nOne of your requirements is to revoke unnecessary privileges from all users who have them using Privilege Analysis.\nWhich two types of analyses can be done using the DBMS_PRIVILEGE_CAPTURE package? (Choose two.)", "options": [{"id": "A", "text": "analysis of privileges that a user has on their own schema objects"}, {"id": "B", "text": "analysis of privileges that a user has on other schema’s objects"}, {"id": "C", "text": "analysis of privileges granted directly to a role that are then used by a user who has been granted that role"}, {"id": "D", "text": "analysis of all privileges used by SYS user."}, {"id": "E", "text": "analysis of privileges granted indirectly to a role that are then used by a user who has been granted that role"}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q71", "sourceId": "64-1", "prompt": "Which two are true about granting privileges on objects? (Choose two.)", "options": [{"id": "A", "text": "An object privilege can be granted to other users only by the owner of that object."}, {"id": "B", "text": "The owner of an object acquires all object privileges on that object by default."}, {"id": "C", "text": "The WITH GRANT OPTION clause can be used only by DBA users."}, {"id": "D", "text": "An object privilege can be granted to a role only by the owner of that object."}, {"id": "E", "text": "A table owner must grant the REFERENCES privilege to allow other users to create FOREIGN KEY constraints using that table."}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q72", "sourceId": "64", "prompt": "Which three statements are true about undo segments and the use of undo by transactions in an Oracle database instance? (Choose three.)", "options": [{"id": "A", "text": "An undo segment may be used by multiple transactions simultaneously"}, {"id": "B", "text": "Undo segments can wrap around to the first extent when a transaction fills the last extend of the undo segment"}, {"id": "C", "text": "Undo segments have a minimum of three extents"}, {"id": "D", "text": "Undo segments can extend when a transaction fills the last extent of the undo segment"}, {"id": "E", "text": "A single transaction may use multiple undo segments simultaneously"}, {"id": "F", "text": "Undo segments must be stored in a BIGFILE tablespace"}, {"id": "G", "text": "Undo segments must be stored in a SMALLFILE tablespace"}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q73", "sourceId": "65", "prompt": "Which two statements are true about Enterprise Manager Database Express? (Choose two.)", "options": [{"id": "A", "text": "It is available only when the database is open"}, {"id": "B", "text": "It can be used to perform database recovery"}, {"id": "C", "text": "The same port number can be used for Database Express configurations for databases on different hosts"}, {"id": "D", "text": "It can be used to switch a database into ARCHIVELOGMODE"}, {"id": "E", "text": "The same port number can be used for multiple Database Express configurations for multiple databases on the same host"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q74", "sourceId": "67", "prompt": "Which two are true about a SQL statement using SET operators such as UNION? (Choose two.)", "options": [{"id": "A", "text": "The data type group of each column returned by the second query must match the data type of the corresponding column returned by the first query."}, {"id": "B", "text": "The number, but not names, of columns must be identical for all SELECT statements in the query."}, {"id": "C", "text": "The data type of each column returned by the second query must exactly match the data type of the corresponding column returned by the first query."}, {"id": "D", "text": "The names and number of columns must be identical for all SELECT statements in the query."}, {"id": "E", "text": "The data type of each column returned by the second query must be implicitly convertible to the data type of the corresponding column returned by the first query."}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q75", "sourceId": "69", "prompt": "Which three statements are true about inner and outer joins? (Choose three.)", "options": [{"id": "A", "text": "A full outer join returns matched and unmatched rows"}, {"id": "B", "text": "An inner join returns matched rows"}, {"id": "C", "text": "Outer joins can only be used between two tables per query"}, {"id": "D", "text": "A full outer join must use Oracle syntax"}, {"id": "E", "text": "Outer joins can be used when there are multiple join conditions on two tables"}, {"id": "F", "text": "A left or right outer join returns only unmatched rows"}], "correct": ["A", "B", "E"], "choose": 3, "scorable": true}, {"id": "q76", "sourceId": "70", "prompt": "Examine this description of the TRANSACTIONS table:\n\n[[IMG:image25.png]]\n\nWhich two SQL statements execute successfully? (Choose two.)", "options": [{"id": "A", "text": "SELECT customer_id AS \"CUSTOMER-ID\", transaction_date AS DATE, amount + 100 \"DUES\" FROM transactions;"}, {"id": "B", "text": "SELECT customer_id AS \"CUSTOMER-ID\", transaction_date AS \"DATE\", amount + 100 DUES FROM transactions;"}, {"id": "C", "text": "SELECT customer_id AS CUSTOMER-ID, transaction_date AS TRANS_DATE, amount + 100 \"DUES AMOUNT\" FROM transactions;"}, {"id": "D", "text": "SELECT customer_id CUSTID, transaction_date TRANS_DATE, amount + 100 DUES FROM transactions;"}, {"id": "E", "text": "SELECT customer_id AS ‘CUSTOMER-ID’, transaction_date AS DATE, amount + 100 ‘DUES AMOUNT’ FROM transactions;"}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q77", "sourceId": "71", "prompt": "The CUSTOMERS table has a CUST_CREDIT_LIMIT column of data type NUMBER.\nWhich two queries execute successfully? (Choose two.)", "options": [{"id": "A", "text": "SELECT NVL(cust_credit_limit * .15, 'Not Available') FROM customers;"}, {"id": "B", "text": "SELECT NVL2(cust_credit_limit * .15, 'Not Available') FROM customers;"}, {"id": "C", "text": "SELECT NVL(TO_CHAR(cust_credit_limit * .15), 'Not Available') FROM customers;"}, {"id": "D", "text": "SELECT TO_CHAR(NVL(cust_credit_limit * .15, 'Not Available')) FROM customers;"}, {"id": "E", "text": "SELECT NVL2(cust_credit_limit, TO_CHAR(cust_credit_limit * .15), 'Not Available') FROM customers;"}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q78", "sourceId": "72", "prompt": "Which statement is true about aggregate functions?", "options": [{"id": "A", "text": "Aggregate functions can be nested to any number of levels"}, {"id": "B", "text": "The AVG function implicitly converts NULLS to zero"}, {"id": "C", "text": "Aggregate functions can be used in any clause of a SELECT statement"}, {"id": "D", "text": "The MAX and MIN functions can be used on columns with character data types"}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q79", "sourceId": "73", "prompt": "Your database instance was shut down normally and then started in NOMOUNT state. You then execute this command:\nALTER DATABASE MOUNT;\nWhich two actions are performed? (Choose two.)", "options": [{"id": "A", "text": "The online redo logs are opened"}, {"id": "B", "text": "The online data files are opened"}, {"id": "C", "text": "The alert log records the execution details"}, {"id": "D", "text": "The Oracle background processes are started"}, {"id": "E", "text": "The initialization parameter file is read"}, {"id": "F", "text": "The control file is read"}], "correct": ["C", "F"], "choose": 2, "scorable": true}, {"id": "q80", "sourceId": "74", "prompt": "Which two are true about shrinking a segment online? (Choose two.)", "options": [{"id": "A", "text": "It is not possible to shrink either indexes or Index Organized Tables (IOTs)"}, {"id": "B", "text": "It always eliminates all migrated rows if any exist in the table"}, {"id": "C", "text": "To shrink a table it must have a PRIMARY KEY constraint"}, {"id": "D", "text": "To shrink a table it must have a UNIQUE KEY constraint"}, {"id": "E", "text": "To shrink a table it must have row movement enabled"}, {"id": "F", "text": "It must be in a tablespace that uses Automatic Segment Space Management (ASSM)"}], "correct": ["E", "F"], "choose": 2, "scorable": true}, {"id": "q81", "sourceId": "75", "prompt": "Examine these commands:\n\n\n[[IMG:image26.jpeg]]\n\nWhich two statements are true about the sqlldr execution?", "options": [{"id": "A", "text": "It overwrites the data for Alan and adds data for Curl and Bob"}, {"id": "B", "text": "It appends data from EMP.DAT to EMP."}, {"id": "C", "text": "It generates a sql script that it uses to load data from EMP.DAT to EMP"}, {"id": "D", "text": "It generates a log that contains control file entries, which can be used with normal SQL*Loader operations."}, {"id": "E", "text": "It overwrites all data in EMP with data from EMP.DAT"}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q82", "sourceId": "76", "prompt": "A script abc.sql must be executed to perform a job.\nA database user HR, who is defined in this database, executes this command:\n$ sqlplus hr/hr@orcl @abc.sql\nWhat will happen upon execution?", "options": [{"id": "A", "text": "The command succeeds and HR will be connected to the orcl and abc.sql databases"}, {"id": "B", "text": "The command succeeds and HR will be connected to the orcl database instance, and the abc.sql script will be executed"}, {"id": "C", "text": "The command fails because the script must refer to the full path name"}, {"id": "D", "text": "The command fails and reports an error because @ is used twice"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q83", "sourceId": "77", "prompt": "Which three statements are true regarding indexes? (Choose three.)", "options": [{"id": "A", "text": "A UNIQUE index can be altered to be non-unique"}, {"id": "B", "text": "A SELECT statement can access one or more indices without accessing any tables"}, {"id": "C", "text": "A table belonging to one user can have an index that belongs to a different user"}, {"id": "D", "text": "An update to a table can result in updates to any or all of the table's indexes"}, {"id": "E", "text": "When a table is dropped and is moved to the RECYCLE BIN, all indexes built on that table are permanently dropped"}, {"id": "F", "text": "An update to a table can result in no updates to any of the table's indexes"}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q84", "sourceId": "78", "prompt": "Which three statements are true about Oracle synonyms? (Choose three.)", "options": [{"id": "A", "text": "A synonym cannot be created for a PL/SQL package"}, {"id": "B", "text": "A synonym can be available to all users"}, {"id": "C", "text": "A SEQUENCE can have a synonym"}, {"id": "D", "text": "A synonym created by one user can refer to an object belonging to another user"}, {"id": "E", "text": "Any user can drop a PUBLIC synonym"}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q85", "sourceId": "79", "prompt": "View the Exhibit and examine the structure of the PRODUCTS table.\nWhich two tasks require subqueries? (Choose two.)", "options": [{"id": "A", "text": "Display the number of products whose PROD_LIST_PRICE is more than the average PROD_LIST_PRICE"}, {"id": "B", "text": "Display suppliers whose PROD_LIST_PRICE is less than 1000"}, {"id": "C", "text": "Display products whose PROD_MIN_PRICE is more than the average PROD_LIST_PRICE of all products, and whose status is orderable"}, {"id": "D", "text": "Display the total number of products supplied by supplier 102 which have a product status of obsolete"}, {"id": "E", "text": "Display the minimum PROD_LIST_PRICE for each product status"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q86", "sourceId": "79-1", "prompt": "Which two are true about the roles? (Choose two.)", "options": [{"id": "A", "text": "All privileges and roles granted to a user are enabled by default when the user logs in."}, {"id": "B", "text": "The ALTER USER statement must be used to set specific default roles for a user."}, {"id": "C", "text": "A role must be disabled before it can be revoked from a user."}, {"id": "D", "text": "The SET ROLE statement can be used once per session."}, {"id": "E", "text": "The SET ROLE statement enables as well as disables roles in a session."}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q87", "sourceId": "79-2", "prompt": "Which three statements about roles are true? (Choose three.)", "options": [{"id": "A", "text": "Roles are assigned to users using the ALTER USER statement."}, {"id": "B", "text": "Privileges are assigned to a role using the GRANT statement."}, {"id": "C", "text": "A role is a named group of related privileges that can only be assigned to a user."}, {"id": "D", "text": "A single user can be assigned multiple roles."}, {"id": "E", "text": "Privileges are assigned to a role using the ALTER ROLE statement."}, {"id": "F", "text": "Roles are assigned to roles using the ALTER ROLE statement."}, {"id": "G", "text": "A single role can be assigned to multiple users."}], "correct": ["B", "D", "G"], "choose": 3, "scorable": true}, {"id": "q88", "sourceId": "79-3", "prompt": "Which three statements are true about roles?", "options": [{"id": "A", "text": "All roles granted to a user are set on by default when the user logs in,"}, {"id": "B", "text": "Object privileges may not be granted to roles."}, {"id": "C", "text": "The SET ROLE statement can disable one or more roles for a session."}, {"id": "D", "text": "Roles must be password protected."}, {"id": "E", "text": "Roles may be granted to roles."}, {"id": "F", "text": "The SET ROLE statement can enable one or more roles for a session."}], "correct": ["C", "E", "F"], "choose": 3, "scorable": true}, {"id": "q89", "sourceId": "80", "prompt": "The SALES_Q1 and USERS tablespaces exist in one of your databases and TEMP is a temporary tablespace.\n\n[[IMG:image27.png]]\n \nSegment creation is not deferred. You execute this command:\nWhich three statements must be true so that the SALES user can create tables in SALES_Q1? (Choose three.)", "options": [{"id": "A", "text": "The sales user must have a quota on the TEMP tablespace"}, {"id": "B", "text": "The sales user must have a quota on the SALES_Q1 tablespace to hold the initial extends of all tables they plan to create in their schema"}, {"id": "C", "text": "The sales user must have been granted the CREATE SESSION privilege"}, {"id": "D", "text": "The sales user must have their quota on the users tablespace removed"}, {"id": "E", "text": "The sales user must have a quota on the SALES_Q1 tablespace to hold all the rows to be inserted into any table in their schema"}, {"id": "F", "text": "The sales user must have been granted the CREATE TABLE privilege"}], "correct": ["B", "C", "F"], "choose": 3, "scorable": true}, {"id": "q90", "sourceId": "81", "prompt": "Which three statements are true about table data storage in an Oracle Database? (Choose three.)", "options": [{"id": "A", "text": "Data block headers contain their own Data Block Address (DBA)"}, {"id": "B", "text": "A table row piece can be chained across several database blocks"}, {"id": "C", "text": "Multiple row pieces from the same row may be stored in different database blocks"}, {"id": "D", "text": "Multiple row pieces from the same row may be stored in the same block"}, {"id": "E", "text": "Data block free space is always contiguous in the middle of the block"}, {"id": "F", "text": "Index block free space is always contiguous in the middle of the block"}], "correct": ["A", "C", "D"], "choose": 3, "scorable": true}, {"id": "q91", "sourceId": "81-2", "prompt": "Which two statements are true about table data storage in an Oracle database?", "options": [{"id": "A", "text": "Multiple row pieces from the same row must be stored in different database blocks."}, {"id": "B", "text": "Index block free space is always contiguous in the middle of the block."}, {"id": "C", "text": "Data block free space is always contiguous in the middle of the block."}, {"id": "D", "text": "A table row can be chained across several database blocks."}, {"id": "E", "text": "Multiple row pieces from the same row may be stored in different database blocks."}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q92", "sourceId": "82", "prompt": "Examine the description of the BOOKS table:\n\n[[IMG:image28.png]]\n\nThe table has 100 rows.\nExamine this sequence of statements issued in a new session:\nINSERT INTO books VALUES ('ADV112', 'Adventures of Tom Sawyer', NULL, NULL);\nSAVEPOINT a;\nDELETE FROM books;\nROLLBACK TO SAVEPOINT a;\nROLLBACK;\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "The second ROLLBACK command does nothing"}, {"id": "B", "text": "The second ROLLBACK command replays the delete"}, {"id": "C", "text": "The first ROLLBACK command restores the 101 rows that were deleted, leaving the inserted row still to be committed"}, {"id": "D", "text": "The second ROLLBACK command undoes the insert"}, {"id": "E", "text": "The first ROLLBACK command restores the 101 rows that were deleted and commits the inserted row"}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q93", "sourceId": "83", "prompt": "Which three statements are true about external tables in Oracle 18c and later releases? (Choose three.)", "options": [{"id": "A", "text": "External table files can be used for other external tables in a different database"}, {"id": "B", "text": "The ORACLE_LOADER access driver can be used to unload data from a database into an external table"}, {"id": "C", "text": "The ORACLE_DATAPUMP access driver can be used to unload data from a database into an external table"}, {"id": "D", "text": "They cannot be partitioned"}, {"id": "E", "text": "The ORACLE_DATAPUMP access driver can be used to load data into a database from an external table"}, {"id": "F", "text": "They support UPDATEs but not INSERTs and DELETEs"}], "correct": ["A", "C", "E"], "choose": 3, "scorable": true}, {"id": "q94", "sourceId": "84", "prompt": "Which three statements are true about the Oracle join and ANSI join syntax? (Choose three.)", "options": [{"id": "A", "text": "The Oracle join syntax supports creation of a Cartesian product of two tables"}, {"id": "B", "text": "The Oracle join syntax performs better than the SQL:1999 compliant ANSI join syntax"}, {"id": "C", "text": "The SQL:1999 compliant ANSI join syntax supports natural joins"}, {"id": "D", "text": "The SQL:1999 compliant ANSI join syntax supports creation of a Cartesian product of two tables"}, {"id": "E", "text": "The Oracle join syntax only supports right outer joins"}, {"id": "F", "text": "The Oracle join syntax supports natural joins"}, {"id": "G", "text": "The Oracle join syntax performs less well than the SQL:1999 compliant ANSI join syntax"}], "correct": ["A", "C", "D"], "choose": 3, "scorable": true}, {"id": "q95", "sourceId": "84-1", "prompt": "Examine these queries and their output:\n\n[[IMG:image29.png]]\n\nAn online RMAN backup of the CDB was taken an hour before Restore Point R1 was created.\nYou want to recover PDB1 to Restore Point R1.\nHow do you achieve this?", "options": [{"id": "A", "text": "Execute FLASHBACK PLUGGABLE DATABASE PDB1 TO RESTORE POINT R1 by using RMAN while connected to PDB1."}, {"id": "B", "text": "Execute FLASHBACK PLUGGABLE DATABASE PDB1 TO RESTORE POINT R1 by using SQL while connected to PDB1."}, {"id": "C", "text": "Execute FLASHBACK PLUGGABLE DATABASE PDB1 TO RESTORE POINT R1 by using SQL while connected to CDB$ROOT."}, {"id": "D", "text": "Execute FLASHBACK PLUGGABLE DATABASE PDB1 TO RESTORE POINT R1 by using RMAN while connected to CDB$ROOT."}, {"id": "E", "text": "This cannot be done due to the lack of a clean restore point."}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q96", "sourceId": "85", "prompt": "Which two tasks can you perform using DBCA for databases? (Choose two.)", "options": [{"id": "A", "text": "Configure a nonstandard block size for a new database"}, {"id": "B", "text": "Register a new database with an available Enterprise Manager Management server"}, {"id": "C", "text": "Change the standard block size of an existing database"}, {"id": "D", "text": "Configure incremental backups for a new database"}, {"id": "E", "text": "Enable flashback database for an existing database"}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q97", "sourceId": "87", "prompt": "Examine this command:\nCREATE UNDO TABLESPACE undotbs01\nDATAFILE 'undotbs_01.dbf'\n\nSIZE 100M -\nAUTOEXTEND ON;\nWhich two actions must you take to ensure UNDOTBS01 is used as the default UNDO tablespace? (Choose two.)", "options": [{"id": "A", "text": "Add the SEGMENT SPACE MANAGEMENT AUTO clause"}, {"id": "B", "text": "Set UNDO_TABLESPACE to UNDOTBS01"}, {"id": "C", "text": "Add the NOLOGGING clause"}, {"id": "D", "text": "Make certain that the database operates in automatic undo management mode"}, {"id": "E", "text": "Add the ONLINE clause"}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q98", "sourceId": "87-2", "prompt": "Examine the description of the MEMBERS table:\n \n\n[[IMG:image30.png]]\n\nExamine the partial query:\nSELECT city, last_name AS lname FROM members ...;\nYou want to display all cities that contain the string AN. The cities must be returned in ascending order, with the last names further sorted in descending order.\nWhich two clauses must you add to the query? (Choose two.)", "options": [{"id": "A", "text": "WHERE city = ‘%AN%’"}, {"id": "B", "text": "Order BY last_name DESC, city ASC"}, {"id": "C", "text": "ORDER BY 1, LNAME DESC"}, {"id": "D", "text": "ORDER BY 1, 2"}, {"id": "E", "text": "WHERE city IN (‘%AN%’)"}, {"id": "F", "text": "WHERE city LIKE ‘%AN%’"}], "correct": ["C", "F"], "choose": 2, "scorable": true}, {"id": "q99", "sourceId": "88", "prompt": "Which three statements are true about views in an Oracle database? (Choose three.)", "options": [{"id": "A", "text": "Views can be updated without the need to re-grant privileges on the view"}, {"id": "B", "text": "Tables in the defining query of a view must always exist in order to create the view"}, {"id": "C", "text": "The WITH CHECK clause prevents certain rows from being displayed when querying the view"}, {"id": "D", "text": "Data Manipulation Language (DML) can always be used on views"}, {"id": "E", "text": "Inserting one or more rows using a view whose defining query contains a GROUP BY clause will cause an error"}, {"id": "F", "text": "Deleting one or more rows using a view whose defining query contains a GROUP BY clause will cause an error"}, {"id": "G", "text": "The WITH CHECK clause prevents certain rows from being updated or inserted"}], "correct": ["A", "F", "G"], "choose": 3, "scorable": true}, {"id": "q100", "sourceId": "132", "prompt": "Choose three. Which three statements are true about views in an Oracle Database?", "options": [{"id": "A", "text": "Rows inserted into a table using a view are retained in the table if the view is dropped."}, {"id": "B", "text": "A view can be created that refers to a non-existent table in its defining query."}, {"id": "C", "text": "Views have no object number."}, {"id": "D", "text": "Views have no segment."}, {"id": "E", "text": "A SELECT statement cannot contain a WHERE clause when querying a view containing a WHERE clause in its defining query."}, {"id": "F", "text": "Views can join tables only if they belong to the same schema."}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q101", "sourceId": "146", "prompt": "Choose three. Which three statements are true about GLOBAL TEMPORARY TABLES?", "options": [{"id": "A", "text": "A GLOBAL TEMPORARY TABLE cannot have PUBLIC SYNONYM."}, {"id": "B", "text": "A GLOBAL TEMPORARY TABLE can have multiple indexes."}, {"id": "C", "text": "A GLOBAL TEMPORARY TABLE can be referenced in the defining query of a view."}, {"id": "D", "text": "Data Manipulation Language (DML) on GLOBAL TEMPORARY TABLES generates no REDO."}, {"id": "E", "text": "A GLOBAL TEMPORARY TABLE can have only one index."}, {"id": "F", "text": "A trigger can be created on a GLOBAL TEMPORARY TABLE."}], "correct": ["B", "C", "F"], "choose": 3, "scorable": true}, {"id": "q102", "sourceId": "89", "prompt": "You execute this command:\nCREATE SMALLFILE TABLESPACE sales\nDATAFILE '/u01/app/oracle/sales01.dbf\n\nSIZE 5G -\nSEGMENT SPACE MANAGEMENT AUTO;\nWhich two statements are true about the SALES tablespace? (Choose two.)", "options": [{"id": "A", "text": "It must be smaller than the smallest BIGFILE tablespace"}, {"id": "B", "text": "Free space is managed using freelists"}, {"id": "C", "text": "Any data files added to the tablespace must have a size of 5 gigabytes"}, {"id": "D", "text": "It uses the database default blocksize"}, {"id": "E", "text": "It is a locally managed tablespace"}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q103", "sourceId": "90", "prompt": "In the SALES database, DEFERRED_SEGMENT_CREATION is TRUE.\nExamine this command:\nSQL> CREATE TABLE T1(c1 INT PRIMARY KEY, c2 CLOB);\nWhich segment or segments, if any, are created as a result of executing the command?", "options": [{"id": "A", "text": "T1, an index segment for the primary key, a LOB segment, and a lobindex segment"}, {"id": "B", "text": "no segments are created"}, {"id": "C", "text": "T1 only"}, {"id": "D", "text": "T1 and an index segment created for the primary key only"}, {"id": "E", "text": "T1, an index segment for the primary key, and a LOB segment only"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q104", "sourceId": "91", "prompt": "Which three activities are recorded in the database alert log? (Choose three.)", "options": [{"id": "A", "text": "Data Definition Language (DDL) statements"}, {"id": "B", "text": "non-default database parameters"}, {"id": "C", "text": "block corruption errors"}, {"id": "D", "text": "deadlock errors"}, {"id": "E", "text": "session logins and logouts"}], "correct": ["B", "C", "D"], "choose": 3, "scorable": true}, {"id": "q105", "sourceId": "91-1", "prompt": "Which two statements are true about space-saving features in an Oracle Database?", "options": [{"id": "A", "text": "Private Temporary Tables (PTTs) when used, are always dropped at the next COMMIT or ROLLBACK statement"}, {"id": "B", "text": "An index that is altered to be UNUSABLE will retain its segment"}, {"id": "C", "text": "An index created with the UNUSABLE attribute has no segment"}, {"id": "D", "text": "Private Temporary Tables (PTTs) store metadata in memory only"}, {"id": "E", "text": "A table that is truncated will always have all of its extents removed"}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q106", "sourceId": "92", "prompt": "Which two statements are true about Enterprise Manager (EM) Express?", "options": [{"id": "A", "text": "You can use a single instance of EM Express to manage multiple database running on the same server."}, {"id": "B", "text": "EM Express uses a separate repository database to store target database metadata."}, {"id": "C", "text": "By default, EM express is available for a database after database creation using DBCA."}, {"id": "D", "text": "You can shut down a database instance using EM Express."}, {"id": "E", "text": "You cannot start up a database instance using EM Express."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q107", "sourceId": "169", "prompt": "Which two statements are true about date/time functions in a session where NLS_DATE_FORMAT is set to DD-MON-YYYY HH24:MI:SS?", "options": [{"id": "A", "text": "SYSDATE can be queried only from the DUAL table."}, {"id": "B", "text": "SYSDATE and CURRENT_DATE return the current date and time set for the operating system of the client"}, {"id": "C", "text": "CURRENT_TIMESTAMP returns the same date and time as SYSDATE with additional details of fractional seconds."}, {"id": "D", "text": "CURRENT_DATE returns the current date and time as per the session time zone.z"}, {"id": "E", "text": "SYSDATE can be used in expressions only if the default date format is DD-MONRR."}, {"id": "F", "text": "CURRENT_TIMESTAMP returns the same date as CURRENT_DATE ."}], "correct": ["D", "F"], "choose": 2, "scorable": true}, {"id": "q108", "sourceId": "185", "prompt": "Choose two. Which two statements are true about CURRENT_TIMESTAMP?", "options": [{"id": "A", "text": "The time is in the time zone of DBTIMEZONE."}, {"id": "B", "text": "It always returns the same value as SYSTIMESTAMP."}, {"id": "C", "text": "The date is in the time zone of DBTIMEZONE."}, {"id": "D", "text": "The value varies depending on the setting of SESSIONTIMEZON"}, {"id": "E", "text": "E)It returns the same date as CURRENT_DATE."}, {"id": "F", "text": "It returns a value of data type TIMESTAMP."}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q109", "sourceId": "210", "prompt": "Choose four. Which four statements are true about the Oracle Server architecture?", "options": [{"id": "A", "text": "A person or program can have more than one session with an instance by logging in with different usernames."}, {"id": "B", "text": "A person or program can have more than one session with an instance by logging in with the same username."}, {"id": "C", "text": "A connection represents the state of a user's login to an instance."}, {"id": "D", "text": "Each server process and background process has their own Program Global Area (PGA)."}, {"id": "E", "text": "The buffer cache and the redo log buffer are held in the large pool."}, {"id": "F", "text": "The entire data dictionary is always cached in the shared pool to improve performance."}, {"id": "G", "text": "A session represents the state of a user's login to an instance"}], "correct": ["A", "B", "D", "G"], "choose": 4, "scorable": true}, {"id": "q110", "sourceId": "24", "prompt": "Which two statements are true about time zones, date data types, and time stamp data types in an Oracle database?", "options": [{"id": "A", "text": "The DBTIME ZONE function can return an offset from Universal Coordinated Time (UTC)."}, {"id": "B", "text": "The SESSIONTIMEZONE function can return an offset from Universal Coordinated Time (UT"}, {"id": "C", "text": ".\nC) The CURRENT_TIMESTAMP function returns data without time zone information."}, {"id": "D", "text": "The DATE data type returns data with time zone information."}, {"id": "E", "text": "A TIMESTAMP WITH LOCAL TIMEZONE data type column is stored in the database using the time zone of the session that inserted the row."}], "correct": ["A", "B", "C"], "choose": 2, "scorable": false}, {"id": "q111", "sourceId": "98", "prompt": "Which three statements are true about time zones, date data types, and timestamp data types in an Oracle database? (Choose three.)", "options": [{"id": "A", "text": "The CURRENT_TIMESTAMP function returns data without time zone information"}, {"id": "B", "text": "A TIMESTAMP WITH LOCAL TIMEZONE data type column is stored in the database using the time zone of the session that inserted the row"}, {"id": "C", "text": "A TIMESTAMP data type column contains information about year, month, and day"}, {"id": "D", "text": "The DBTIMEZONE function can return an offset from Universal Coordinated Time (UTC)"}, {"id": "E", "text": "The SESSIONTIMEZONE function can return an offset from Universal Coordinated Time (UTC)"}], "correct": ["C", "D", "E"], "choose": 3, "scorable": true}, {"id": "q112", "sourceId": "99", "prompt": "Choose three. Which three statements are true about CURRENT_TIMESTAMP?", "options": [{"id": "A", "text": "The value varies depending on the setting of SESSIONTIMEZONE."}, {"id": "B", "text": "The date is in the time zone of DBTIMEZONE."}, {"id": "C", "text": "It returns a value of data type TIMESTAMP."}, {"id": "D", "text": "The time is in the time zone of DBTIMEZON"}, {"id": "E", "text": "E)It returns the same date as CURRENT_DATE."}, {"id": "F", "text": "It always returns the same value as SYSTIMESTAMP."}, {"id": "G", "text": "It returns the same time as CURRENT_DATE."}], "correct": ["A", "E", "G"], "choose": 3, "scorable": true}, {"id": "q113", "sourceId": "99-1", "prompt": "Which three statements are true about multiple row subqueries?", "options": [{"id": "A", "text": "They can contain GROUP BY clauses."}, {"id": "B", "text": "They can return multiple columns."}, {"id": "C", "text": "Two or more values are always returned from the subquery."}, {"id": "D", "text": "They can contain HAVING clauses."}, {"id": "E", "text": "They cannot contain a subquery."}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q114", "sourceId": "99-2", "prompt": "Which two statements are true regarding the COUNT function? (Choose two.)", "options": [{"id": "A", "text": "COUNT(*) returns the number of rows including duplicate rows and rows containing NULL value in any of the columns"}, {"id": "B", "text": "COUNT(cust_id) returns the number of rows including rows with duplicate customer IDs and NULL value in the CUST_ID column"}, {"id": "C", "text": "COUNT(DISTINCT inv_amt) returns the number of rows excluding rows containing duplicates and NULL values in the INV_AMT column"}, {"id": "D", "text": "A SELECT statement using COUNT function with a DISTINCT keyword cannot have a WHERE clause"}, {"id": "E", "text": "The COUNT function can be used only for CHAR, VARCHAR2 and NUMBER data types"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q115", "sourceId": "93", "prompt": "Examine this SQL statement:\nSELECT cust_id, cust_last_name `Last Name`\n\nFROM customers -\n\nWHERE country_id = 10 -\n\nUNION -\nSELECT cust_id CUST_NO, cust_last_name\n\nFROM customers -\n\nWHERE country_id = 30 -\nIdentify three ORDER BY clauses, any one of which can complete the query successfully. (Choose three.)", "options": [{"id": "A", "text": "ORDER BY ג€Last Nameג€"}, {"id": "B", "text": "ORDER BY 2, 1"}, {"id": "C", "text": "ORDER BY 2, cust_id"}, {"id": "D", "text": "ORDER BY CUST_NO"}, {"id": "E", "text": "ORDER BY ג€CUST_NOג€"}], "correct": ["A", "B", "C"], "choose": 3, "scorable": true}, {"id": "q116", "sourceId": "94", "prompt": "Which two statements are true about the configuration and use of UNDO_RETENTION with GURANTEED RETENTION? (Choose two.)", "options": [{"id": "A", "text": "UNDO_RETENTION specifies for how long Oracle attempts to keep expired and unexpired UNDO."}, {"id": "B", "text": "UNDO_RETENTION specifies how long all types of UNDO are retained."}, {"id": "C", "text": "Unexpired UNDO is always retained."}, {"id": "D", "text": "Active UNDO is always retained."}, {"id": "E", "text": "UNDO_RETENTION specifies for how long Oracle attempts to keep unexpired UNDO."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q117", "sourceId": "95", "prompt": "Table ORDER_ITEMS contains columns ORDER_ID, UNIT_PRICE and QUANTITY, of data type NUMBER.\nExamine these SQL statements:\nStatement 1:\nSELECT MAX(unit_price * quantity) `Maximum Order`\nFROM order_items;\nStatement 2:\nSELECT MAX(unit_price * quantity) `Maximum Order`\n\nFROM order_items -\nGROUP BY order_id;\nWhich two statements are true?", "options": [{"id": "A", "text": "Statement 1 returns only one row of output."}, {"id": "B", "text": "Statement 2 returns only one row of output."}, {"id": "C", "text": "Both statements will return NULL if either UNIT_PRICE or QUANTITY contains NULL."}, {"id": "D", "text": "Both the statements give the same output."}, {"id": "E", "text": "Statement 2 may return multiple rows of output."}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q118", "sourceId": "96", "prompt": "Which three files are used by conventional path SQL*Loader when the TABLE option is not specified? (Choose three.)", "options": [{"id": "A", "text": "dump files"}, {"id": "B", "text": "control files"}, {"id": "C", "text": "password files"}, {"id": "D", "text": "bad files"}, {"id": "E", "text": "input files"}], "correct": ["B", "D", "E"], "choose": 3, "scorable": true}, {"id": "q119", "sourceId": "97", "prompt": "Which three statements are true about the naming methods and their features supported by Oracle database used to resolve connection information? (Choose three.)", "options": [{"id": "A", "text": "Local Naming requires setting the TNS_ADMIN environment variable on the client side."}, {"id": "B", "text": "A client can connect to an Oracle database instance even if no client side network admin has been configured."}, {"id": "C", "text": "Directory Naming can be used if Connect-Time Failover is required."}, {"id": "D", "text": "Easy Connect supports TCP/IP and SSL."}, {"id": "E", "text": "Local naming can be used if Connect-Time Failover is required."}, {"id": "F", "text": "Directory Naming requires setting the TNS_ADMIN environment variable on the client side."}], "correct": ["A", "B", "E"], "choose": 3, "scorable": true}, {"id": "q120", "sourceId": "98", "prompt": "Which two statements are true about User Authentication in an Oracle Database? (Choose two.)", "options": [{"id": "A", "text": "Password authentication must be used for system-privileged administrative users."}, {"id": "B", "text": "Password File authentication must be used for system-privileged administrative users."}, {"id": "C", "text": "Operating System authentication may be used for system-privileged administrative users."}, {"id": "D", "text": "Password File authentication is supported for any type of database user."}, {"id": "E", "text": "REMOTE_LOGIN_PASSWORDFILE must be set to exclusive to permit password changes for system-privileged administrative users."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q121", "sourceId": "98-1", "prompt": "You start your database instance in NOMOUNT state\nWhich two actions are performed?", "options": [{"id": "A", "text": "Memory is allocated for the SGA"}, {"id": "B", "text": "The consistency of the database is checked"}, {"id": "C", "text": "All required background processes are started"}, {"id": "D", "text": "SYS can access the database"}, {"id": "E", "text": "The control files are opened"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q122", "sourceId": "99-1", "prompt": "You currently have an active transaction in your session and have been granted SELECT access to V$TRANSACTION.\nExecuting:\nSELECT xid, status FROM v$transaction;\nIn your session returns:\n\n[[IMG:image31.png]]\n\nIn which three situations will re-executing this query still return a row but with a different XID, indicating a new transaction as started?", "options": [{"id": "A", "text": "After successfully executing a CREATE TABLE AS SELECT statement followed by a SELECT FOR UPDATE statement"}, {"id": "B", "text": "After successfully executing a DML statement following a failed DML statement"}, {"id": "C", "text": "After successfully executing a CREATE TABLE statement followed by a CREATE INDEX statement"}, {"id": "D", "text": "After successfully executing a COMMIT or ROLLBACK followed by a SELECT statement"}, {"id": "E", "text": "After successfully executing a TRUNCATE statement followed by a DML statement"}, {"id": "F", "text": "After successfully executing a COMMIT or ROLLBACK followed by a DML statement"}], "correct": ["A", "E", "F"], "choose": 3, "scorable": true}, {"id": "q123", "sourceId": "99", "prompt": "Which is the default column or columns for sorting output from compound queries using SET operators such as INTERSECT in a SQL statement?", "options": [{"id": "A", "text": "the first NUMBER column in the first SELECT of the compound query"}, {"id": "B", "text": "the first NUMBER or VARCHAR2 column in the last SELECT of the compound query"}, {"id": "C", "text": "the first column in the last SELECT of the compound query"}, {"id": "D", "text": "the first column in the first SELECT of the compound query"}, {"id": "E", "text": "the first VARCHAR2 column in the first SELECT of the compound query"}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q124", "sourceId": "101", "prompt": "Which two statements are true about UNDO and UNDO tablespaces? (Choose two.)", "options": [{"id": "A", "text": "There can be only one UNDO tablespace created in a database."}, {"id": "B", "text": "UNDO segments are owned by SYSTEM."}, {"id": "C", "text": "UNDO segments are owned by SYSBACKUP."}, {"id": "D", "text": "An UNDO tablespace may be owned by only one instance."}, {"id": "E", "text": "An instance will crash if the active undo tablespace is lost."}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q125", "sourceId": "102", "prompt": "You must create a tablespace of non-standard block size in a new file system and plan to use this command:\n\n[[IMG:image32.png]]\n\n\n\nThe standard block size is 8k but other non-standard block sizes will also be used.\n\nWhich two are requirements for this command to succeed? (Choose two.)", "options": [{"id": "A", "text": "DB_32K_CACHE_SIZE must be less than DB_CACHE_SIZE."}, {"id": "B", "text": "DB_32K_CACHE_SIZE must be set to a value that can be accommodated in the SGA."}, {"id": "C", "text": "DB_32K_CACHE_SIZE should be set to a value greater than DB_CACHE_SIZE."}, {"id": "D", "text": "The /u02 file system must have at least 100g space for the datafile."}, {"id": "E", "text": "The operating system must use a 32k block size."}, {"id": "F", "text": "DB_CACHE_SIZE must be set to a size that is smaller than DB_32K_CACHE_SIZE."}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q126", "sourceId": "103", "prompt": "Examine the description of the PRODUCTS table:\n\n\n[[IMG:image33.png]]\n\n\nWhich query is valid?", "options": [{"id": "A", "text": "SELECT prod_id, release_date, SUM(cost) FROM products GROUP BY prod_id;"}, {"id": "B", "text": "SELECT prod_id, release_date, SUM(cost) FROM products GROUP BY prod_id, release_date;"}, {"id": "C", "text": "SELECT prod_id, AVG(MAX(cost)) FROM products GROUP BY prod_id;"}, {"id": "D", "text": "SELECT prod_id, MAX(AVG(cost)) FROM products GROUP BY prod_id;"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q127", "sourceId": "104", "prompt": "Which two statements are true about the Oracle Data Dictionary? (Choose two.)", "options": [{"id": "A", "text": "All data dictionary view join base tables to dynamic performance views."}, {"id": "B", "text": "Data dictionary base tables can be queried directly."}, {"id": "C", "text": "It is owned by the SYS user."}, {"id": "D", "text": "It is owned by the SYSTEM user."}, {"id": "E", "text": "Data dictionary views are always created with queries that join two or more base tables."}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q128", "sourceId": "106", "prompt": "Which three statements are true about connection strings and service names used to connect to an Oracle database instance? (Choose three.)", "options": [{"id": "A", "text": "A connection string must include the SID of a database instance."}, {"id": "B", "text": "A connection string including a service name must be defined in the tnsnames.ora file."}, {"id": "C", "text": "A single database instance can support connections for multiple service names."}, {"id": "D", "text": "A single connection string can refer to multiple database instances."}, {"id": "E", "text": "A service name is created by a listener."}, {"id": "F", "text": "Different connection strings in the same tnsnames.ora file can contain the same service name, host and port parameters."}], "correct": ["C", "D", "F"], "choose": 3, "scorable": true}, {"id": "q129", "sourceId": "107", "prompt": "Which three statements are true about using SQL*Plus? (Choose three.)", "options": [{"id": "A", "text": "It has both command-line and graphical user interfaces (GUI)."}, {"id": "B", "text": "It must be downloaded from the Oracle Technology Network (OTN)."}, {"id": "C", "text": "It can run Recovery Manager (RMAN) commands."}, {"id": "D", "text": "It has its own commands that are separate from any SQL statements."}, {"id": "E", "text": "It can run scripts entered at the SQL prompt."}, {"id": "F", "text": "It can run scripts passed to it by a shell script."}], "correct": ["D", "E", "F"], "choose": 3, "scorable": true}, {"id": "q130", "sourceId": "108", "prompt": "", "options": [], "correct": [], "choose": 0, "scorable": false}, {"id": "q131", "sourceId": "18", "prompt": "18. The orders table has a column ORDER_DATE of data type DATE.\n\nThe default display format for a date is DD-MON-RR.\n\nWhich two WHERE conditions demonstrate the correct usage of conversion functions? (Choose two.)", "options": [{"id": "A", "text": "WHERE order_date > TO_DATE(ADD_MONTHS(SYSDATE, 6), 'MON DD YYYY')"}, {"id": "B", "text": "WHERE order dare > TO DATE('JUL 10 2018', 'MON DD YYYY')"}, {"id": "C", "text": "WHERE TO_CHAR(order date, 'MON DD YYYY') = 'JAN 20 2019'"}, {"id": "D", "text": "WHERE order_date > TO_CHAR(ADD_MONTHS(SYSDATE, 6), 'MON DD YYYY')"}, {"id": "E", "text": "WHERE order_date IN (TO_DATE('Oct 21 2018', 'Mon DD YYYY'), TO_CHAR('Nov 21 2018', 'Mon DD YYYY'))"}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q132", "sourceId": "110", "prompt": "Which two statements are true about a self join? (Choose two.)", "options": [{"id": "A", "text": "It can be an inner join."}, {"id": "B", "text": "It can be a left outer join."}, {"id": "C", "text": "It must be an equijoin."}, {"id": "D", "text": "The join key column must have an index."}, {"id": "E", "text": "It must be a full outer join."}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q133", "sourceId": "111", "prompt": "Which statement is true about database links?", "options": [{"id": "A", "text": "Private database link creation requires the same user to exist in both the local and the remote databases."}, {"id": "B", "text": "A database link created in a database allows a connection from that database's instance to the target database's instance, but not vice versa."}, {"id": "C", "text": "A public database link can be used by a user connected to the local database instance to connect to any schema in the remote database instance."}, {"id": "D", "text": "A public database link can be created only by SYS."}, {"id": "E", "text": "A database link can be created only between two Oracle databases."}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q134", "sourceId": "113", "prompt": "Which three statements are true about data block storage in an Oracle Database? (Choose three.)", "options": [{"id": "A", "text": "An index block can contain row data."}, {"id": "B", "text": "A data block header is of a fixed length."}, {"id": "C", "text": "Row data is stored starting at the end of the block."}, {"id": "D", "text": "A table block must always contain row data."}, {"id": "E", "text": "A block header contains a row directory pointing to all rows in the block."}], "correct": ["A", "C", "E"], "choose": 3, "scorable": true}, {"id": "q135", "sourceId": "114", "prompt": "Which two are benefits of external tables? (Choose two.)", "options": [{"id": "A", "text": "They support DELETES which transparently deletes records in the file system as if they were table rows."}, {"id": "B", "text": "They can be queried, transformed, and joined with other tables without having to load the data first."}, {"id": "C", "text": "They support UPDATES which transparently updates records in the file system as if they were table rows."}, {"id": "D", "text": "The results of a complex join or aggregating function or both can be unloaded to a file for transportation to another database."}, {"id": "E", "text": "They can be queried while the database is in the MOUNT state like dynamic performance views."}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q136", "sourceId": "116", "prompt": "Which three statements are true about sequences in a single instance Oracle database? (Choose three.)", "options": [{"id": "A", "text": "Sequences can always have gaps."}, {"id": "B", "text": "Two or more tables cannot have keys generated from the same sequence."}, {"id": "C", "text": "A sequence's unallocated cached values are lost if the instance shuts down."}, {"id": "D", "text": "A sequence can issue duplicate values."}, {"id": "E", "text": "A sequence can only be dropped by a DBA."}, {"id": "F", "text": "A sequence number that was allocated can be rolled back if a transaction fails."}], "correct": ["A", "C", "D"], "choose": 3, "scorable": true}, {"id": "q137", "sourceId": "116-1", "prompt": "Examine the description of the EMPLOYEES table:\n\n[[IMG:image34.jpeg]]\n\nWhich query is valid?", "options": [{"id": "A", "text": "SELECT dept_id, AVG(MAX(salary)) FROM employees GROUP BY dept_id;"}, {"id": "B", "text": "SELECT dept_id, join_date, SUM(salary) FROM employees GROUP BY dept_id;"}, {"id": "C", "text": "SELECT dept_id, join_date, SUM(salary) FROM employees GROUP BY dept_id, join_date;"}, {"id": "D", "text": "SELECT dept_id, MAX(AVG(salary)) FROM employees GROUP BY dept_id;"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q138", "sourceId": "116-2", "prompt": "You need to calculate the number of days from 1st January 2019 until today. Dates are stored in the default format of DD-MON-RR.\nWhich two queries give the required output? (Choose two.)", "options": [{"id": "A", "text": "SELECT TO_CHAR(SYSDATE, ‘DD-MON-YYYY’) – ’01-JAN-2019′ FROM DUAL;"}, {"id": "B", "text": "SELECT ROUND(SYSDATE – ’01-JAN-2019′) FROM DUAL;"}, {"id": "C", "text": "SELECT ROUND(SYSDATE – TO_DATE(’01/JANUARY/2019′)) FROM DUAL;"}, {"id": "D", "text": "SELECT TO_DATE (SYSDATE, ‘DD/MONTH/YYYY’) – ’01/JANUARY/2019′ FROM DUAL;"}, {"id": "E", "text": "SELECT SYSDATE – TO_DATE (’01-JAN-2019′) FROM DUAL;"}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q139", "sourceId": "117", "prompt": "Your database instance is started with an SPFILE.\n\nA PFILE is also available.\n\nYou execute this command:\n\nALTER SYSTEM SET DB_CACHE_SIZE=100K;\n\nWhere is the value changed?", "options": [{"id": "A", "text": "in the SPFILE, PFILE, and memory"}, {"id": "B", "text": "in the SPFILE and in memory"}, {"id": "C", "text": "only in the SPFILE"}, {"id": "D", "text": "only in memory"}, {"id": "E", "text": "in the SPFILE and PFILE"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q140", "sourceId": "119", "prompt": "Examine the description of the SALES table:\n\n[[IMG:image35.png]]\n\n\n\nThe SALES table has 55,000 rows.\n\nExamine this statement:\n\n[[IMG:image36.png]]\n\n\n\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "SALES1 is created with l row."}, {"id": "B", "text": "SALES1 is created with no rows."}, {"id": "C", "text": "SALES1 has primary KEY and UNIQUE constraints on any selected columns which had those constraints in the SALES table."}, {"id": "D", "text": "SALES1 has NOT NULL constraints on any selected columns which had those constraints in the SALES table."}, {"id": "E", "text": "SALES1 is created with 55,000 rows."}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q141", "sourceId": "120", "prompt": "Which three statements are true about performing Data Manipulation Language (DML) operations on a view with no INSTEAD OF triggers defined? (Choose three.)", "options": [{"id": "A", "text": "Views cannot be used to query rows from an underlying table if the table has a PRIMARY KEY and the PRIMARY KEY columns are not referenced in the defining query of the view."}, {"id": "B", "text": "The WITH CHECK clause has no effect when deleting rows from the underlying table through the view."}, {"id": "C", "text": "Delete statements can always be done on a table through a view."}, {"id": "D", "text": "Views cannot be used to add or modify rows in an underlying table if the defining query of the view contains the DISTINCT keyword."}, {"id": "E", "text": "Views cannot be used to add rows to an underlying table if the table has columns with NOT NULL constraints lacking default values which are not referenced in the defining query of the view."}, {"id": "F", "text": "Insert statements can always be done on a table through a view."}], "correct": ["A", "B", "C", "D"], "choose": 3, "scorable": false}, {"id": "q142", "sourceId": "121", "prompt": "Which three statements are true about indexes and their administration in an Oracle database? (Choose three.)", "options": [{"id": "A", "text": "An index can be created as part of a CREATE TABLE statement."}, {"id": "B", "text": "If a query filters on an indexed column, then it will always be used during execution of the query."}, {"id": "C", "text": "A descending index is a type of function-based index."}, {"id": "D", "text": "A DROP INDEX statement always prevents updates to the table during the drop operation."}, {"id": "E", "text": "A UNIQUE and non-unique index can be created on the same table column."}, {"id": "F", "text": "An INVINSIBLE INDEX is not maintained when Data Manipulation Language (DML) is performed on its underlying table."}], "correct": [], "choose": 3, "scorable": false}, {"id": "q143", "sourceId": "195", "prompt": "Choose three. Which three statements are true about indexes and their administration in an Oracle database?", "options": [{"id": "A", "text": "The same table column can be part of a unique and non-unique index."}, {"id": "B", "text": "If a query filters on an indexed column then it will always be used during execution of the query."}, {"id": "C", "text": "A descending index is a type of function-based index。"}, {"id": "D", "text": "An INVISIBLE index is not maintained when DML is performed on its underlying table. DML INVISIBLE"}, {"id": "E", "text": "An UNUSABLE index is maintained when DML is performed on its underlying table. DML UNUSABLE"}, {"id": "F", "text": "An index can be created as part of a CREATE TABLE statement. CREATE TABLE"}], "correct": ["A", "C", "F"], "choose": 3, "scorable": true}, {"id": "q144", "sourceId": "196", "prompt": "Choose the best answer. Examine these statements which execute successfully:\nALTER SESSION SET NLS_DATE_FORMAT = 'DD-MON-YYYY HH24:MI:SS' ;\nALTER SESSION SET TIME_ZONE = '-5:00' ;\nSELECT DBTIMEZONE, SYSDATE FROM DUAL;\nExamine the result:\nDBTIMEZONE SYSDATE\n------------- ------------------------------------------\n+00.00 11- JUL-2019 11:00:00\nIf LOCALTIMESTAMP was selected at the same time, what would it return?", "options": [{"id": "A", "text": "11-JUL-2019 6.00.00.00000000 AM"}, {"id": "B", "text": "11-JUL-2019 11.00.00.00000000 AM"}, {"id": "C", "text": "11-JUL-2019 11.00.00.0000000 AM -05:00"}, {"id": "D", "text": "11-JUL-2019 6.00.00.00000000 AM -05:00"}], "correct": ["A"], "choose": 1, "scorable": true}, {"id": "q145", "sourceId": "202", "prompt": "Choose two. You have been granted the CREATE ANY INDEX system privilege. You want to create an index, owned by you, on a table in another schema to which you have been granted only the SELECT privilege. Which two are true?", "options": [{"id": "A", "text": "You must have either the UNLIMITED TABLESPACE system privilege, or sufficient quota on the tablespace where the index will be created."}, {"id": "B", "text": "You additionally require the INSERT, UPDATE, DELETE, and INDEX privileges on the table."}, {"id": "C", "text": "You do not require any further object privileges on the table."}, {"id": "D", "text": "You additionally require only the INDEX privilege on the table."}, {"id": "E", "text": "The owner of the table must also have the CREATE ANY INDEX system privilege."}, {"id": "F", "text": "The owner of the table must have either the UNLIMITED TABLESPACE system privilege, or sufficient quota on the tablespace where the index will be created."}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q146", "sourceId": "204", "prompt": "Choose two. Which two statements are true regarding non-equijoins?", "options": [{"id": "A", "text": "The USING clause can be used."}, {"id": "B", "text": "Table aliases must be used."}, {"id": "C", "text": "The Oracle join syntax can be used."}, {"id": "D", "text": "The SQL:1999 compliant ANSI join syntax must be used."}, {"id": "E", "text": "The ON clause can be used."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q147", "sourceId": "122", "prompt": "Which three actions are ways to apply the principle of least privilege? (Choose three.)", "options": [{"id": "A", "text": "setting the O7_DICTIONARY_ACCESSIBILITY parameter to true"}, {"id": "B", "text": "setting the REMOTE_OS_AUTHENT parameter to true"}, {"id": "C", "text": "revoking execute privilege on UTL_SMTP, UTL_TCP, UTL_HTTP, and UTL_FILE from the SYSTEM user"}, {"id": "D", "text": "enabling Unified Auditing"}, {"id": "E", "text": "using Access Control Lists (ACLs)"}, {"id": "F", "text": "revoking execute privilege on UTL_SMTP, UTL_TCP, UTL_HTTP, and UTL_FILE from the public user"}], "correct": ["D", "E", "F"], "choose": 3, "scorable": true}, {"id": "q148", "sourceId": "123", "prompt": "The STORES table has a column START_DATE of data type DATE, containing the date the row was inserted.\n\nYou only want to display details of rows where START_DATE is within the last 25 months.\n\nWhich WHERE clause can be used?", "options": [{"id": "A", "text": "WHERE ADD_MONTHS(start_date, 25) <= SYSDATE"}, {"id": "B", "text": "WHERE MONTHS_BETWEEN(start_date, SYSDATE) <= 25"}, {"id": "C", "text": "WHERE MONTHS_BETWEEN(SYSDATE, start_date) <=25"}, {"id": "D", "text": "WHERE TO_NUMBER(start date - SYSDAT"}, {"id": "E", "text": "<= 25"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q149", "sourceId": "124", "prompt": "Examine the description of the BOOKS_TRANSACTIONS table:\n\n[[IMG:image37.png]]\n\n\n\nExamine this partial SQL statement:\n\nSELECT * FROM books_transactions\n\nWhich two WHERE conditions give the same result? (Choose two.)", "options": [{"id": "A", "text": "WHERE borrowed_date = SYSDATE AND (transaction_type = 'RM' AND member_id = 'A101' OR member_id = 'A102');"}, {"id": "B", "text": "WHERE borrowed_date = SYSDATE AND transaction_type = 'RM' OR member_id IN ('A101', 'A102');"}, {"id": "C", "text": "WHERE borrowed_date = SYSDATE AND (transaction_type = 'RM' AND (member_id = 'A101' OR member_id = 'A102'));"}, {"id": "D", "text": "WHERE borrowed_date = SYSDATE AND (transaction_type = 'RM' OR menber_id IN ('A101', 'A102'));"}, {"id": "E", "text": "WHERE (borrowed_date = SYSDATE AND transaction_type - 'RM') OR member_id IN ('A101', VA102');"}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q150", "sourceId": "125", "prompt": "Which two statements are true about views? (Choose two.)", "options": [{"id": "A", "text": "The WITH CHECK clause prevents certain rows from being updated or inserted in the underlying table through the view."}, {"id": "B", "text": "The WITH CHECK clause prevents certain rows from being displayed when querying the view."}, {"id": "C", "text": "Views can be updated without the need to re-grant privileges on the view."}, {"id": "D", "text": "A view must only refer to tables in its defining query."}, {"id": "E", "text": "Views can be indexed."}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q151", "sourceId": "128", "prompt": "Examine these statements executed in a single Oracle session:\n\n[[IMG:image38.png]]\n\n\n\nWhich three statements are true? (Choose three.)", "options": [{"id": "A", "text": "The code for pen is 10."}, {"id": "B", "text": "There is no row containing fountain pen."}, {"id": "C", "text": "There is no row containing pen."}, {"id": "D", "text": "The code for fountain pen is 3."}, {"id": "E", "text": "The code for pen is l."}, {"id": "F", "text": "There is no row containing pencil."}], "correct": ["A", "D", "F"], "choose": 3, "scorable": true}, {"id": "q152", "sourceId": "129", "prompt": "Examine the description of the SALES1 table:\n\n[[IMG:image39.png]]\n\n\n\nSALES2 is a table with the same description as SALES1.\n\nSome sales data is contained erroneously in both tables.\n\nYou must display rows from SALES1 and SALES2 and wish to see the duplicates too.\n\nWhich set operator generates the required output?", "options": [{"id": "A", "text": "UNION ALL"}, {"id": "B", "text": "SUBTRACT"}, {"id": "C", "text": "MINUS"}, {"id": "D", "text": "UNION"}, {"id": "E", "text": "INTERSECT"}], "correct": ["C"], "choose": 1, "scorable": true}, {"id": "q153", "sourceId": "130", "prompt": "In the promotions table, the PROMO_BEGIN_DATE column is of data type DATE and the default date format is DD-MON-RR.\n\nWhich two statements are true about expressions using PROMO_BEGIN_DATE contained in a query? (Choose two.)", "options": [{"id": "A", "text": "TO_NUMBER(PROMO_BEGIN_DATE) - 5 will return a number."}, {"id": "B", "text": "PROMO_BEGIN_DATE - SYSDATE will return an error."}, {"id": "C", "text": "PROMO_BEGIN_DATE - SYSDATE will return a number."}, {"id": "D", "text": "PROMO_BEGIN_DATE - 5 will return a date."}, {"id": "E", "text": "TO_DATE(PROMO_BEGIN_DATE * 5) will return a date."}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q154", "sourceId": "131", "prompt": "Which two statements are true regarding indexes? (Choose two.)", "options": [{"id": "A", "text": "A non-unique index can be altered to be unique."}, {"id": "B", "text": "An update to a table can result in no updates to any of the table's indexes."}, {"id": "C", "text": "The RECYCLE BIN never contains indexes."}, {"id": "D", "text": "An update to a table can result in updates to any or all of the table's indexes."}, {"id": "E", "text": "A table belonging to one user cannot have an index that belongs to a different user."}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q155", "sourceId": "181", "prompt": "Choose two. Which two are true about virtual columns?", "options": [{"id": "A", "text": "They can be referenced in the WHERE clause of an UPDATE or DELETE statement."}, {"id": "B", "text": "They cannot have a data type explicitly specified."}, {"id": "C", "text": "They can be indexed."}, {"id": "D", "text": "They can be referenced in the SET clause of an UPDATE statement as the name of the column to be updated."}, {"id": "E", "text": "They can be referenced in the column expression of another virtual column."}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q156", "sourceId": "132", "prompt": "Which three statements are true regarding single row subqueries? (Choose three.)", "options": [{"id": "A", "text": "A SQL statement may have multiple single row subquery blocks."}, {"id": "B", "text": "They can be used in the WHERE clause."}, {"id": "C", "text": "They must be placed on the left side of the comparison operator or condition."}, {"id": "D", "text": "They can be used in the HAVING clause."}, {"id": "E", "text": "They must be placed on the right side of the comparison operator or condition."}, {"id": "F", "text": "They must return a row to prevent errors in the SQL statement."}], "correct": ["A", "B", "D"], "choose": 3, "scorable": true}, {"id": "q157", "sourceId": "132-1", "prompt": "The ORCL database has RESUMABLE_TIMEOUT = 7200 and DEFERED_SEGMENT_CREATION= FALSE\n\nUser U1 has a 1 MB quota in tablespace DAT", "options": [{"id": "A", "text": "U1 executes this command:\n       SQL> CREATE TABLE t1 AS\n       (SELECT object_name, sharing, created FROM dba_objects);\n\nU1 complains that the command is taking too long to execute. In the alert log, the database administrator (DBA) finds this:\n2017-03-06T12:15:17.183438+05:30\nstatement in resumable session ‘User U1(136), Session 1, Instance 1’ was suspended due to ORA-01536: space quota exceeded for tablespace ‘DATA’\nWhich are three actions any one of which the DBA could take to resume the session? (Choose three.)\nA) Add a data file to DATA"}, {"id": "B", "text": "Drop other U1 objects in DATA"}, {"id": "C", "text": "Increase U1’s quota sufficiently in DATA"}, {"id": "D", "text": "Set DEFERRED_SEGMENT_CREATION to TRUE"}, {"id": "E", "text": "Grant UNLIMITED TABLESPACE to U1"}, {"id": "F", "text": "Set AUTOEXTEND ON for data files in DATA"}], "correct": ["B", "C", "E"], "choose": 1, "scorable": false}, {"id": "q158", "sourceId": "133", "prompt": "Which two statements are true about Oracle synonyms? (Choose two.)", "options": [{"id": "A", "text": "Any user can create a public synonym."}, {"id": "B", "text": "A synonym has an object number."}, {"id": "C", "text": "A synonym can be created on an object in a package."}, {"id": "D", "text": "All private synonym names must be unique in the database."}, {"id": "E", "text": "A synonym can have a synonym."}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q159", "sourceId": "133-1", "prompt": "Which are two of the account management capabilities that can be configured using Oracle profiles? (Choose two.)", "options": [{"id": "A", "text": "the maximum amount of CPU time allowed for a user’s sessions before their account is locked"}, {"id": "B", "text": "the ability to prevent a password from ever being reused"}, {"id": "C", "text": "the number of days for which an account may be logged in to one or more sessions before it is locked.\nF) the maximum number of sessions permitted for a user before the password must be changed.\nE) the number of days for which an account may be inactive before it is locked."}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q160", "sourceId": "133-1", "prompt": "Which two are benefits of external tables?", "options": [{"id": "A", "text": "They can be queried while the database is in the MOUNT state like dynamic performance views."}, {"id": "B", "text": "They support DELETE which transparently deletes records in the file system as if they were table rows."}, {"id": "C", "text": "They can be queried, transformed, and joined with other tables without having to load the data first."}, {"id": "D", "text": "They support UPDATES which transparently updates records in the file system as if they were table rows."}, {"id": "E", "text": "The results of a complex join or aggregating function or both can be unloaded to a file for transportation to another database."}], "correct": ["C", "E"], "choose": 2, "scorable": true}, {"id": "q161", "sourceId": "134", "prompt": "Examine this command:\n\nSQL> ALTER TABLE ORDERS SHRINK SPACE COMPACT\n\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "The SHRINK operation causes rows to be moved to empty space starting from the beginning of the ORDERS segment."}, {"id": "B", "text": "Queries and DML statements are allowed on ORDERS while the SHRINK is executing."}, {"id": "C", "text": "Dependent indexes become UNUSABLE."}, {"id": "D", "text": "Only queries are allowed on ORDERS while the shrink is executing."}, {"id": "E", "text": "The high-water mark (HWM) of ORDERS is adjusted."}, {"id": "F", "text": "The SHRINK operation causes rows to be moved to empty space starting toward the end of the ORDERS segment."}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q162", "sourceId": "135", "prompt": "The sales table has columns PROD_ID and QUANTITY_SOLD of data type number.\n\nWhich two queries execute successfully? (Choose two.)", "options": [{"id": "A", "text": "SELECT COUNT(prod_id) FROM sales WHERE quantity_sold > 55000 GROUP BY prod_id;"}, {"id": "B", "text": "SELECT COUNT(prod_id) FROM sales GROUP BY prod_id WHERE quantity_sold > 55000;"}, {"id": "C", "text": "SELECT prod_id FROM sales WHERE quantity_sold > 55000 AND COUNT(*) > 10 GROUP BY COUNT(*) > 10;"}, {"id": "D", "text": "SELECT prod_id FROM sales WHERE quantity_sold > 55000 GROUP BY proa_id HAVING COUNT(*) > 10;"}, {"id": "E", "text": "SELECT prcd_id FROM sales WHERE quantity_sold > 55000 AND COUNT (*) > 10 GROUP BY prod_id HAVING COUNT(*) > 10;"}], "correct": ["A", "D"], "choose": 2, "scorable": true}, {"id": "q163", "sourceId": "136", "prompt": "Examine the description of the PRODUCT_DETAILS table:\n\n[[IMG:image40.png]]\n\n\n\nWhich two statements are true? (Choose two.)", "options": [{"id": "A", "text": "PRODUCT_ID can be assigned the PRIMARY KEY constraint."}, {"id": "B", "text": "EXPIRY_DATE cannot be used in arithmetic expressions."}, {"id": "C", "text": "PRODUCT_NAME cannot contain duplicate values."}, {"id": "D", "text": "EXPIRY_DATE contains the SYSDATE by default if no date is assigned to it."}, {"id": "E", "text": "PRODUCT_PRICE can be used in an arithmetic expression even if it has no value stored in it."}, {"id": "F", "text": "PRODUCT_PRICE contains the value zero by default if no value is assigned to it."}], "correct": ["A", "E"], "choose": 2, "scorable": true}, {"id": "q164", "sourceId": "137", "prompt": "Which two statements are true about INTERVAL data types? (Choose two.)", "options": [{"id": "A", "text": "INTERVAL DAY TO SECOND columns support fractions of seconds."}, {"id": "B", "text": "The YEAR field in an INTERVAL YEAR TO MONTH column must be a positive value."}, {"id": "C", "text": "The value in an INTERVAL DAY TO SECOND column can be copied into an INTERVAL YEAR TO MONTH column."}, {"id": "D", "text": "INTERVAL YEAR TO MONTH columns only support monthly intervals within a range of years."}, {"id": "E", "text": "INTERVAL YEAR TO MONTH columns only support monthly intervals within a single year."}, {"id": "F", "text": "INTERVAL YEAR TO MONTH support yearly intervals."}], "correct": ["A", "F"], "choose": 2, "scorable": true}, {"id": "q165", "sourceId": "6", "prompt": "You have been tasked to create a table for a banking application.\nOne of the columns must meet three requirements:\n1. Be stored in a format supporting date arithmetic without using conversion functions\n2. Store a loan period of up to 10 years\n3. Be used for calculating interest for the number of days the loan remains unpaid\nWhich data type should you use?", "options": [{"id": "A", "text": "INTERVAL YEAR TO MONTH"}, {"id": "B", "text": "INTERVAL DAY TO SECOND"}, {"id": "C", "text": "TIMESTAMP WITH LOCAL TIMEZONE"}, {"id": "D", "text": "TIMESTAMP"}, {"id": "E", "text": "TIMESTAMP WITH TIMEZONE"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q166", "sourceId": "138", "prompt": "Examine the description of the EMPLOYEES table:\n\n\n[[IMG:image41.png]]\n\nNLS_DATE_FORMAT is set to DD-MON-YY.\n\nWhich query requires explicit data type conversion?", "options": [{"id": "A", "text": "SELECT join_date FROM employees WHERE join_date > '10-02-2018';"}, {"id": "B", "text": "SELECT join_date + '20' FROM employees;"}, {"id": "C", "text": "SELECT salary + '120.50' FROM employees;"}, {"id": "D", "text": "SELECT SUBSTR(join_date, 1, 2) - 10 FROM employees;"}, {"id": "E", "text": "SELECT join_date || ' ' || salary FROM employees;"}], "correct": ["A"], "choose": 1, "scorable": true}, {"id": "q167", "sourceId": "139", "prompt": "You start your database instance in NOMOUNT state.\n\nWhich two actions are performed? (Choose two.)", "options": [{"id": "A", "text": "SYS can access the database."}, {"id": "B", "text": "The consistency of the database is checked."}, {"id": "C", "text": "The control files are opened."}, {"id": "D", "text": "All required background processes are started."}, {"id": "E", "text": "Memory is allocated for the SGA."}], "correct": ["D", "E"], "choose": 2, "scorable": true}, {"id": "q168", "sourceId": "140-5", "prompt": "Which two statements are true about the PMON background process? (Choose two.)", "options": [{"id": "A", "text": "It registers database services with all local and remote listeners known to the database instance"}, {"id": "B", "text": "It frees resources held by abnormally terminated processes"}, {"id": "C", "text": "It records checkpoint information in the control file"}, {"id": "D", "text": "It frees unused temporary segments"}, {"id": "E", "text": "It kills sessions that exceed idle time"}], "correct": ["B", "E"], "choose": 2, "scorable": true}, {"id": "q169", "sourceId": "140", "prompt": "Which two statements are true about the PMON background process? (Choose two.)", "options": [{"id": "A", "text": "It registers database services with all local and remote listeners known to the database instance."}, {"id": "B", "text": "It frees unused temporary segments."}, {"id": "C", "text": "It rolls back transactions when a process fails."}, {"id": "D", "text": "It records checkpoint information in the control file."}, {"id": "E", "text": "It frees resources held by abnormally terminated processes."}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q170", "sourceId": "140-1", "prompt": "Which two are true about transactions in the Oracle Database?", "options": [{"id": "A", "text": "A session can see uncommitted updates made by the same user in a different session."}, {"id": "B", "text": "A DDL statement issued by a session with an uncommitted transaction automatically commits that transaction."}, {"id": "C", "text": "An uncommitted transaction is automatically committed when the user exits SQL*Plus."}, {"id": "D", "text": "DDL statements automatically commit only data dictionary updates caused by executing the DDL."}, {"id": "E", "text": "DML statements always start new transactions."}], "correct": ["B", "C"], "choose": 2, "scorable": true}, {"id": "q171", "sourceId": "140-2", "prompt": "Which two queries execute successfully?", "options": [{"id": "A", "text": "SELECT COALESCE (100, NULL, 200) FROM DUAL;"}, {"id": "B", "text": "SELECT NULLIF(100, 100) FROM DUAL;"}, {"id": "C", "text": "SELECT NULLIF(NULL, 100) FROM DUAL;"}, {"id": "D", "text": "SELECT COALESCE(100, ‘A’) FROM DUAL;"}, {"id": "E", "text": "SELECT NULLIF(100, ‘A’) FROM DUAL;"}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q172", "sourceId": "141", "prompt": "Which two statements are true about the Oracle join and ANSI join syntax? (Choose two.)", "options": [{"id": "A", "text": "The Oracle join syntax performs less well than the SQL:1999 compliant ANSI join syntax."}, {"id": "B", "text": "The Oracle join syntax lacks the ability to do outer joins."}, {"id": "C", "text": "The SQL:1999 compliant ANSI join syntax supports creation of a Cartesian product of two tables."}, {"id": "D", "text": "The Oracle join syntax supports creation of a Cartesian product of two tables."}, {"id": "E", "text": "The Oracle join syntax performs better than the SQL:1999 compliant ANSI join syntax."}], "correct": ["C", "D"], "choose": 2, "scorable": true}, {"id": "q173", "sourceId": "145", "prompt": "Which two statements are true about substitution variables? (Choose two.)", "options": [{"id": "A", "text": "A substitution variable can be used with any clause in a SELECT statement."}, {"id": "B", "text": "A substitution variable used to prompt for a column name must be enclosed in double quotation marks."}, {"id": "C", "text": "A substitution variable used to prompt for a column name must be enclosed in single quotation marks."}, {"id": "D", "text": "A substitution variable prefixed with & always prompts only once for a value in a session."}, {"id": "E", "text": "A substitution variable can be used only in a SELECT statement."}, {"id": "F", "text": "A substitution variable prefixed with && prompts only once for a value in a session unless it is set to undefined in the session."}], "correct": ["E", "F"], "choose": 2, "scorable": true}, {"id": "q174", "sourceId": "146", "prompt": "The CUSTOMERS table has a CUST_LAST_NAME column of data type VARCHAR2.\n\nThe table has two rows whose CUST_LAST_NAME values are Anderson and Ausson.\n\nWhich query produces output for CUST_LAST_NAME containing Oder for the first row and Aus for the second?", "options": [{"id": "A", "text": "SELECT REPLACE(SUBSTR(cust_last_name, -3), 'An', 'O') FROM customers;"}, {"id": "B", "text": "SELECT REPLACE(TRIM(TRAILING 'son' FROM cust_last_name), 'An', 'O') FROM customers;"}, {"id": "C", "text": "SELECT INITCAP(REPLACE(TRIM('son' FROM cust_last_name), 'An', 'O')) FROM customers;"}, {"id": "D", "text": "SELECT REPLACE(REPLACE(cust_last_name, 'son', ''), 'An', 'O') FROM customers;"}], "correct": ["D"], "choose": 1, "scorable": true}, {"id": "q175", "sourceId": "158", "prompt": "Choose three. Which three statements are true about single-row functions?", "options": [{"id": "A", "text": "They can accept only one argument."}, {"id": "B", "text": "They can be nested to any level."}, {"id": "C", "text": "They return a single result row per table."}, {"id": "D", "text": "The data type returned can be different from the data type of the argument."}, {"id": "E", "text": "The argument can be a column name, variable, literal or an expression."}, {"id": "F", "text": "They can be used only in the WHERE clause of a SELECT statement."}], "correct": ["B", "D", "F"], "choose": 3, "scorable": true}, {"id": "q176", "sourceId": "149", "prompt": "Examine the description of the PRODUCT_INFORMATION table:\n\n[[IMG:image42.png]]\n\n\n\nWhich query retrieves the number of products with a null list price?", "options": [{"id": "A", "text": "SELECT COUNT(list_price) FROM product_information WHERE list_price IS NULL;"}, {"id": "B", "text": "SELECT COUNT(NVL(list_price, 0)) FROM product_information WHERE list_price IS NULL;"}, {"id": "C", "text": "SELECT COUNT(DISTINCT list price) FROM product_information WHERE list_price IS NULL;"}, {"id": "D", "text": "SELECT COUNT(list_price) FROM product_information WHERE list_price = NULL;"}], "correct": ["B"], "choose": 1, "scorable": true}, {"id": "q177", "sourceId": "150", "prompt": "Examine the description of the CUSTOMERS table:\n\n[[IMG:image43.png]]\n\n\n\nYou must determine if any customers' details have been entered more than once using a different CUSTINO, by listing all duplicate names.\n\nWhich two methods can you use to get the required result? (Choose two.)", "options": [{"id": "A", "text": "subquery"}, {"id": "B", "text": "self join"}, {"id": "C", "text": "LEFT OUTER JOIN with self join"}, {"id": "D", "text": "RIGHT OUTER JOIN With self join"}, {"id": "E", "text": "FULL OUTER JOIN with self join"}], "correct": ["A", "B"], "choose": 2, "scorable": true}, {"id": "q178", "sourceId": "151", "prompt": "Which two statements are true about undo segments and the use of undo by transactions in an Oracle database instance? (Choose two.)", "options": [{"id": "A", "text": "Undo segments can be stored in the SYSAUX tablespace."}, {"id": "B", "text": "Undo segments can wrap around to the first extent when a transaction fills the last extend of the undo segment."}, {"id": "C", "text": "A single transaction may use multiple undo segments simultaneously."}, {"id": "D", "text": "Undo segments can extend when a transaction fills the last extent of the undo segment."}, {"id": "E", "text": "Undo segments can be stored in the SYSTEM tablespace."}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q179", "sourceId": "151-1", "prompt": "Which two statements are true about Database Instances and Real Application Clusters (RAC)?", "options": [{"id": "A", "text": "A RAC database must have two or more instances."}, {"id": "B", "text": "A RAC database can have Instances on separate servers."}, {"id": "C", "text": "Two RAC databases can share their instances."}, {"id": "D", "text": "A RAC database can have one instance"}, {"id": "E", "text": "A RAC database must have three or more instances."}], "correct": ["B", "D"], "choose": 2, "scorable": true}, {"id": "q180", "sourceId": "153", "prompt": "Which two statements are true about Enterprise Manager Database Express? (Choose two.)", "options": [{"id": "A", "text": "It is available only when the database is open"}, {"id": "B", "text": "It can be used to perform database recovery when the database is opened"}, {"id": "C", "text": "The same port number can be used for Database Express configurations for databases on different hosts"}, {"id": "D", "text": "It can be used to switch a database into ARCHIVELOGMODE"}, {"id": "E", "text": "The same port number can be used for multiple Database Express configurations for multiple databases on the same host"}, {"id": "F", "text": "It can be used to perform database recovery when the database is mounted"}], "correct": ["A", "C"], "choose": 2, "scorable": true}, {"id": "q181", "sourceId": "154", "prompt": "Examine these SQL statements which execute successfully:\n\n\n[[IMG:image44.png]]\n\n\nWhich two statements are true after execution? (Choose two.)", "options": [{"id": "A", "text": "The primary key constraint will be enabled and IMMEDIATE."}, {"id": "B", "text": "The primary key constraint will be enabled and DEFERRED."}, {"id": "C", "text": "The foreign key constraint will be enabled and DEFERRE"}, {"id": "D", "text": "D. The foreign key constraint will be disabled."}, {"id": "E", "text": "The foreign key constraint will be enabled and IMMEDIATE."}], "correct": ["A", "D"], "choose": 2, "scorable": true}];

